----------------------------------------------------------------- numbers

local function hash(a, b, c)
  local h = (a * 374761393 + b * 668265263 + c * 2246822519 + SEED * 3266489917) & 0xFFFFFFFF
  h = ((h ~ (h >> 15)) * 2246822519) & 0xFFFFFFFF
  h = ((h ~ (h >> 13)) * 3266489917) & 0xFFFFFFFF
  return h ~ (h >> 16)
end

local function h01(a, b, c) return hash(a, b, c) / 4294967296.0 end

-- a counter run through a mixing function: every number is well mixed,
-- the first ones after the seed too
local function newrng(seed)
  local s = seed & 0xFFFFFFFF
  return function()
    s = (s + 0x9E3779B9) & 0xFFFFFFFF
    local z = ((s ~ (s >> 16)) * 0x85EBCA6B) & 0xFFFFFFFF
    z = ((z ~ (z >> 13)) * 0xC2B2AE35) & 0xFFFFFFFF
    return (z ~ (z >> 16)) / 4294967296.0
  end
end

local function irange(r, a, b) return a + floor(r() * (b - a + 1)) end
local function pick(r, t) return t[floor(r() * #t) + 1] end
local function key2(a, b) return a * 1000003 + b end
local function fdiv(a, b) return floor(a) // b end   -- an integer, from pixels that may not be

----------------------------------------------------------------- the street plan
-- Streets run between the chunks, from corner to corner: every chunk is a
-- block with a street on each side (a few are missing), winding, of its own
-- width and paving. Corners, sides and districts depend only on their
-- coordinates, so neighbouring chunks agree on the streets they share.

local PV_COBBLE, PV_SETTS, PV_FLAGS, PV_ALLEY, PV_WARM, PV_MARBLE, PV_DARK, PV_WET = 1, 2, 3, 4, 5, 6, 7, 8

local corners, edges, districts = {}, {}, {}
-- The paving of a quarter (3 x 3 blocks): all its streets have the same,
-- the next quarter perhaps another (the user's wish: the ground in larger
-- zones of one kind, not a mosaic)
local quarter_pave
do
  local QUARTER = { PV_COBBLE, PV_COBBLE, PV_WARM, PV_SETTS, PV_WET, PV_COBBLE, PV_DARK }
  function quarter_pave(i, j) return QUARTER[hash(i // 3, j // 3, 41) % #QUARTER + 1] end
end

-- The hunt: areas of AREA x AREA chunks in a row eastwards (and AREA chunks
-- tall), each ending with its boss in a district of its kind; the next area
-- opens when the boss falls, so the hunter cannot just walk on for ever.
-- Each area has two hunter's lamps to light: one half way, one before the
-- boss. Echoes: what the slain leave; they heal, they buy strength at a
-- lamp, a death costs some, and without them the hunt is lost.
local AREA = 4
local BOSS_KIND = { "pyre", "park", "cemetery", "chapel" }
local BOSS_NAME = { pyre = "butcher", park = "hound", cemetery = "father", chapel = "watcher" }
local G = { open = 1, echoes = 0, lit = {}, spawn = nil, lost = false, popups = {}, slots = {} }
local function boss_chunk(a) return a * AREA + AREA - 1, a % 2 == 0 and AREA - 1 or 0 end
local function lamp_chunk(a, k)             -- k = 1 half way, 2 before the boss
  local bx, by = boss_chunk(a)
  if k == 2 then return bx - 1, by end
  return a * AREA + 1, a % 2 == 0 and 2 or 1
end
-- chunks the hunter may walk: the areas open so far
local function inside(cx, cy) return cy >= 0 and cy < AREA and cx >= 0 and cx < G.open * AREA end

-- The town has an order (the user's wish): where the blocks round a corner
-- are all town (houses, squares, pyres, chapels: not parks nor cemeteries)
-- the corner is on the grid and the streets between such blocks run
-- straight, every third one an avenue; by the parks and cemeteries the
-- streets wind as they please. (urban is set once district is known.)
local urban

local function corner(i, j)
  local k = key2(i, j)
  local c = corners[k]
  if not c then
    local h = hash(i, j, 1)
    c = { x = i * CS + (h % 5) - 2, y = j * CS + ((h >> 3) % 5) - 2,
          plaza = (h >> 6) % 100 < 28, r = 3.6 + ((h >> 13) % 4) * 0.6 }
    if urban(i - 1, j - 1) and urban(i, j - 1) and urban(i - 1, j) and urban(i, j) then
      c.x, c.y, c.grid = i * CS, j * CS, true
    end
    corners[k] = c
  end
  return c
end

-- the street from corner (i, j) eastwards (dir 0) or southwards (dir 1)
local function edge(i, j, dir)
  local k = key2(i, j) * 2 + dir
  local e = edges[k]
  if e == nil then
    local h = hash(i, j, 2 + dir)
    -- in town: straight; on a quarter's border (every third line) an avenue,
    -- never missing, with lamps on both pavements; else lamps on one side
    local town = dir == 0 and urban(i, j - 1) and urban(i, j) or dir == 1 and urban(i - 1, j) and urban(i, j)
    local avenue = town and (dir == 0 and j or i) % 3 == 0
    if h % 100 < 12 and not avenue and not (abs(i) <= 1 and abs(j) <= 1) then
      e = false
    else
      local a = corner(i, j)
      local b = dir == 0 and corner(i + 1, j) or corner(i, j + 1)
      local w = town and (avenue and 6 or 4) or 4 + (h >> 8) % 3
      e = { a = a, b = b, dir = dir, hw = w / 2,
            A = ((h >> 12) % 61) / 10 - 3.0, B = ((h >> 18) % 21) / 10 - 1.0, pave = quarter_pave(i, j) }
      if town then
        e.A, e.B, e.town = 0, 0, true
        e.lamps = avenue and { 1, -1 } or { (h >> 24) % 2 == 0 and 1 or -1 }
        e.lsp = avenue and 12 or 10                    -- tiles between two lamps of a row
        e.lph = (h >> 26) % e.lsp
      end
      -- how far across its line the street can reach: tiles further are not on it
      local va, vb = dir == 0 and a.y or a.x, dir == 0 and b.y or b.x
      local reach = abs(e.A) + abs(e.B) + e.hw + 0.5
      e.lo, e.hi = min(va, vb) - reach, max(va, vb) + reach
    end
    edges[k] = e
  end
  return e
end

local function edge_dist(e, x, y)
  local a, b = e.a, e.b
  local u, v, ua, va, ub, vb
  if e.dir == 0 then u, v, ua, va, ub, vb = x, y, a.x, a.y, b.x, b.y
  else u, v, ua, va, ub, vb = y, x, a.y, a.x, b.y, b.x end
  if u < ua or u > ub then
    local du, dv
    if u < ua then du, dv = u - ua, v - va else du, dv = u - ub, v - vb end
    return sqrt(du * du + dv * dv)
  end
  local t = (u - ua) / (ub - ua)
  local c = va + (vb - va) * t + e.A * sin(PI * t) + e.B * sin(2 * PI * t)
  return abs(v - c)
end

local NAME_A = { "Ash", "Raven", "Gaunt", "Black", "Mourn", "Hollow", "Wither", "Crane", "Vigil", "Ember",
  "Gallows", "Iron", "Bell", "Thorn", "Grave", "Lantern", "Crow", "Cinder", "Moth", "Pale", "Weeping",
  "Lamb", "Tallow", "Bone", "Fog", "Wick", "Rook", "Gloam", "Candle", "Mire", "Saint Agnes", "Old Mill" }
local NAME_B = { " Lane", " Row", " Street", " Close", " Walk", " Yard", " Court", " Alley", " Hill", " Way" }
local SAINTS = { "St. Agnes", "St. Cyril", "St. Edith", "St. Ludo", "St. Mora", "St. Bram", "the Vigil" }

local function district(cx, cy)
  local k = key2(cx, cy)
  local d = districts[k]
  if d then return d end
  local h = hash(cx, cy, 7)
  local v = (h % 1000) / 1000
  local kind = "town"
  if cx == 0 and cy == 0 then kind = "square"
  elseif v < 0.10 then kind = "cemetery"
  elseif v < 0.17 then kind = "park"
  elseif v < 0.24 then kind = "square"
  elseif v < 0.29 then kind = "pyre"
  elseif v < 0.34 then kind = "chapel" end
  -- the arena at the end of an area: the boss's kind of district
  local bossy = false
  if cx >= 0 and cy >= 0 and cy < AREA then
    local bx, by = boss_chunk(cx // AREA)
    if cx == bx and cy == by then kind, bossy = BOSS_KIND[(cx // AREA) % 4 + 1], true end
  end
  d = { kind = kind, boss = bossy }
  if kind == "square" then d.plaza, d.prx, d.pry, d.pcy = PV_FLAGS, 5.6, 5.0, 8
  elseif kind == "pyre" then d.plaza, d.prx, d.pry, d.pcy = PV_FLAGS, 5.2, 4.6, 8
  elseif kind == "chapel" then d.plaza, d.prx, d.pry, d.pcy = PV_MARBLE, 5.4, 2.4, 13.0 end
  if kind == "town" and (h >> 12) % 100 < 40 then
    d.alley = { dir = (h >> 20) % 2, p = 5 + (h >> 22) % 6, k = 1 + (h >> 25) % 2, ph = (h >> 27) % 6 }
  end
  local a = NAME_A[(h >> 3) % #NAME_A + 1]
  local s = SAINTS[(h >> 9) % #SAINTS + 1]
  if kind == "cemetery" then d.name = a .. " Cemetery"
  elseif kind == "park" then d.name = a .. " Gardens"
  elseif kind == "square" then d.name = a .. " Square"
  elseif kind == "pyre" then d.name = "The " .. a .. " Pyre"
  elseif kind == "chapel" then d.name = "Chapel of " .. s
  else d.name = a .. NAME_B[(h >> 14) % #NAME_B + 1] end
  districts[k] = d
  return d
end

function urban(cx, cy)
  local k = district(cx, cy).kind
  return k ~= "park" and k ~= "cemetery"
end

-- the sides of chunk (cx, cy), and the streets that meet at its corners
local function near_edges(cx, cy)
  local t = {}
  local list = {
    { cx, cy, 0 }, { cx, cy + 1, 0 }, { cx, cy, 1 }, { cx + 1, cy, 1 },
    { cx - 1, cy, 0 }, { cx + 1, cy, 0 }, { cx - 1, cy + 1, 0 }, { cx + 1, cy + 1, 0 },
    { cx, cy - 1, 1 }, { cx + 1, cy - 1, 1 }, { cx, cy + 1, 1 }, { cx + 1, cy + 1, 1 },
  }
  for _, l in ipairs(list) do
    local e = edge(l[1], l[2], l[3])
    if e then t[#t + 1] = e end
  end
  return t
end

-- paving of world tile (tx, ty), 0 = not a street
local function road_at(tx, ty, ne)
  local x, y = tx + 0.5, ty + 0.5
  local cx, cy = tx // CS, ty // CS
  for dj = 0, 1 do
    for di = 0, 1 do
      local c = corner(cx + di, cy + dj)
      if c.plaza then
        local dx, dy = x - c.x, y - c.y
        if dx * dx + dy * dy < c.r * c.r then return PV_FLAGS end
      end
    end
  end
  local d = district(cx, cy)
  local lx, ly = x - cx * CS, y - cy * CS
  if d.plaza then
    local dx, dy = (lx - 8) / d.prx, (ly - d.pcy) / d.pry
    if dx * dx + dy * dy < 1 then return d.plaza end
  end
  local al = d.alley
  if al then
    local u, v = lx, ly
    if al.dir == 1 then u, v = ly, lx end
    if abs(v - al.p - 0.5) < 1.0 then return PV_ALLEY end      -- a straight lane through the block
  end
  ne = ne or near_edges(cx, cy)
  for i = 1, #ne do
    local e = ne[i]
    local v = e.dir == 0 and y or x
    if v > e.lo and v < e.hi and edge_dist(e, x, y) < e.hw then return e.pave end
  end
  return 0
end

----------------------------------------------------------------- chunks

local K_FREE, K_ROAD, K_WALK, K_HOUSE, K_YARD, K_GRASS, K_PATH = 0, 1, 2, 3, 4, 5, 6
local FMATS = { "brick", "ashlar", "stucco", "dark", "brick", "stucco" }
local RMATS = { "slate", "tile", "lead", "copper", "slate", "slate", "tile" }
local GRAVES = { "grave_round", "grave_round2", "grave_cross", "grave_celtic", "grave_obelisk", "grave_broken",
  "grave_slab" }

local lamp_state = {}                    -- lamps lit by the hunter: key -> true
local lamps_lit = 0
local chunks, slots = {}, {}

-- things that break (the user's wish: the streets less in the way, more
-- alive): the wooden ones, and what is left of each. A blow, a roll or a
-- run into them, a creature's blow or slam, a shot breaks them: they stop
-- blocking the way. Broken, they stay so (gone: by chunk and object) until
-- the town fills again (FOE.reset: a lamp, a death)
local BRK = { kinds = { barrel = "barrel_broken", crate = "crate_broken", crates = "crates_broken",
                        bench = "bench_broken", coffin = "coffin_broken", coffin_up = "coffin_up_broken" },
              gone = {}, count = 0 }

-- objects: { s = sprite, x, y (the base, world pixels), z = sort key, ... }
local function add_obj(ch, name, x, y, z, col)
  local s = SPR[name]
  local o = { s = s, x = x, y = y, z = z or y, name = name }
  ch.objs[#ch.objs + 1] = o
  if col then
    local c = { x = x, y = y + (col.dy or 0), rx = col[1], ry = col[2] }
    ch.cols[#ch.cols + 1] = c
    o.c = c
    if BRK.kinds[name] then
      o.col, o.key = c, key2(ch.cx, ch.cy) * 512 + #ch.objs
      if BRK.gone[o.key] then BRK.wreck(o) end
    end
  end
  return o
end

local function add_light(ch, x, y, r, lv, fl, dither)
  ch.lights[#ch.lights + 1] = { x = x, y = y, r = r, lv = lv, fl = fl or 0, d = dither or 0.5,
    seed = (x * 7 + y * 13) % 97 }
end

local function gen(ch)
  local cx, cy = ch.cx, ch.cy
  local tx0, ty0 = cx * CS, cy * CS
  local px0, py0 = tx0 * TS, ty0 * TS
  local d = district(cx, cy)
  local r = newrng(hash(cx, cy, 11))
  local ne = near_edges(cx, cy)

  -- the streets over the chunk and one tile around it
  local road = {}
  for ly = -1, CS do
    local row = (ly + 1) * 18 + 2
    for lx = -1, CS do road[row + lx] = road_at(tx0 + lx, ty0 + ly, ne) end
  end
  local function RD(lx, ly) return road[(ly + 1) * 18 + 2 + lx] end

  local kind, solid, A, B = {}, {}, {}, {}
  ch.kind, ch.solid = kind, solid
  for ly = 0, CS - 1 do
    for lx = 0, CS - 1 do
      local i = ly * CS + lx + 1
      solid[i] = false
      if RD(lx, ly) > 0 then
        kind[i] = K_ROAD
      else
        local nr = false
        for dy = -1, 1 do
          for dx = -1, 1 do
            if RD(lx + dx, ly + dy) > 0 then nr = true end
          end
        end
        kind[i] = nr and K_WALK or K_FREE
      end
    end
  end
  local function K(lx, ly) return kind[ly * CS + lx + 1] end
  local function wx(lx) return px0 + lx * TS + 8 end
  local function wy(ly) return py0 + ly * TS + 8 end
  local used = {}                       -- cells taken by a prop
  local function take(lx, ly) used[ly * CS + lx + 1] = true end
  local function freecell(lx, ly, k)
    return lx >= 0 and ly >= 0 and lx < CS and ly < CS and K(lx, ly) == (k or K_FREE)
           and not used[ly * CS + lx + 1]
  end

  ------------------------------------------------- buildings
  local function rect_free(x0, y0, w, h)
    if x0 < 0 or y0 < 0 or x0 + w > CS or y0 + h > CS then return false end
    for y = y0, y0 + h - 1 do
      for x = x0, x0 + w - 1 do
        if kind[y * CS + x + 1] ~= K_FREE then return false end
      end
    end
    return true
  end

  local function building(x0, y0, w, h, mat, roof, big)
    local cells = {}
    for y = y0, y0 + h - 1 do
      for x = x0, x0 + w - 1 do
        kind[y * CS + x + 1] = K_HOUSE
        solid[y * CS + x + 1] = true
      end
    end
    local function T(i, j, c) cells[j * w + i + 1] = c end
    local rows = h - 5
    -- the front in order: the door in the middle, the windows mirrored
    -- about it (which are lit stays a matter of chance, pair by pair)
    local door = (w - 1) // 2
    local lit_p = big and 0.55 or 0.3
    local fks = {}
    for i = 1, w - 2 do
      local m = w - 1 - i
      if i == door then fks[i] = r() < 0.5 and "door_lit" or "door"
      elseif m < i and m ~= door then fks[i] = fks[m]
      elseif r() < 0.12 and not big then fks[i] = "plain"
      else
        local u, g = r() < lit_p, r() < lit_p
        fks[i] = (u and g) and "win_ug" or u and "win_u" or g and "win_g" or "win"
      end
    end
    for i = 0, w - 1 do
      local side = i == 0 and "l" or i == w - 1 and "r" or "m"
      local R = ROOF[roof]
      for j = 0, rows - 1 do
        local t
        if j == 0 then t = R.ridge[side]
        elseif j == rows - 1 then t = R.eaves[side]
        else t = (j % 2 == 1) and R.slope[side] or R.slope2[side] end
        T(i, j, t)
      end
      local fk = i == 0 and "left" or i == w - 1 and "right" or fks[i]
      local fc = FACADE[mat][fk]
      for j = 0, 4 do T(i, rows + j, fc[j + 1]) end
      local fx, fb = wx(x0 + i), py0 + (y0 + h) * TS
      if fk == "win_g" or fk == "win_ug" then add_light(ch, fx, fb - 20, 26, 3, 0, 0.7) end
      if fk == "door_lit" then add_light(ch, fx, fb - 6, 24, 3, 0, 0.7) end
    end
    local bottom = py0 + (y0 + h) * TS
    local o = { bld = cells, x = px0 + x0 * TS, y = bottom, top = py0 + y0 * TS, w = w, h = h, z = bottom }
    ch.objs[#ch.objs + 1] = o
    -- chimneys on the ridge, a pair at the ends or one in the middle, some smoking
    local n = big and 0 or irange(r, 0, 2)
    local at = n == 2 and { 0, w - 1 } or n == 1 and { door } or {}
    for _, i in ipairs(at) do
      local c = add_obj(ch, r() < 0.5 and "chimney" or "chimney1", wx(x0 + i), py0 + y0 * TS + 14, bottom + 0.5)
      if r() < 0.45 then ch.smokes[#ch.smokes + 1] = { x = c.x, y = c.y - 30 } end
    end
    if big then
      add_obj(ch, "spire", px0 + (x0 + w / 2) * TS, py0 + (y0 + 1) * TS + 6, bottom + 0.5)
    end
  end

  local function place_buildings(big)
    if big then
      for yb = CS - 4, 7, -1 do
        for w = 11, 8, -1 do
          for x = 0, CS - w do
            if rect_free(x, yb - 7, w, 8) then
              building(x, yb - 7, w, 8, "dark", "lead", true)
              goto placed
            end
          end
        end
      end
      ::placed::
    end
    -- rows of houses (terraces): one height and one roof to a row, two
    -- fronts in turn, the free length split into houses of about one width
    for yb = CS - 1, 6, -1 do
      local h = r() < 0.55 and 7 or 8
      if yb - h + 1 >= 0 then
        local roof, fa, fb = pick(r, RMATS), pick(r, FMATS), pick(r, FMATS)
        local x = 0
        while x < CS do
          if rect_free(x, yb - h + 1, 1, h) then
            local L = 1
            while x + L < CS and rect_free(x + L, yb - h + 1, 1, h) do L = L + 1 end
            if L >= 3 then
              local n = max(1, floor(L / 5.5 + 0.5))
              while L / n > 7 do n = n + 1 end
              while n > 1 and L / n < 3 do n = n - 1 end
              local px = x
              for k = 1, n do
                local w = floor(L * k / n) - floor(L * (k - 1) / n)
                building(px, yb - h + 1, w, h, k % 2 == 1 and fa or fb, roof)
                px = px + w
              end
            end
            x = x + L
          else
            x = x + 1
          end
        end
      end
    end
  end

  ------------------------------------------------- districts
  -- (sparse: the user's wish, streets and yards not crowded)
  local yard_props = { { "tree", 0.015, { 6, 3 } }, { "tree2", 0.012, { 5, 3 } }, { "bush", 0.025, { 9, 4 } },
    { "bush2", 0.02, { 8, 4 } }, { "barrel", 0.012, { 6, 3 } }, { "crates", 0.008, { 6, 3 } },
    { "crate", 0.01, { 6, 3 } }, { "well", 0.004, { 10, 5 } } }

  -- (dens: how thick they grow here, round 1)
  local function scatter(list, k, dens)
    for ly = 0, CS - 1 do
      for lx = 0, CS - 1 do
        if freecell(lx, ly, k) then
          local m = dens and dens(lx, ly) or 1
          for _, p in ipairs(list) do
            if r() < p[2] * m then
              take(lx, ly)
              add_obj(ch, p[1], wx(lx) + irange(r, -3, 3), wy(ly) + irange(r, -2, 4), nil, p[3])
              break
            end
          end
        end
      end
    end
  end

  -- in the open the trees grow as they will: in clumps, clearings between
  local gs1, gs2 = h01(cx, cy, 61) * 6.3, h01(cx, cy, 62) * 6.3
  local function grove(lx, ly)
    local g = 0.5 + 0.5 * sin((tx0 + lx) * 0.42 + gs1) * sin((ty0 + ly) * 0.36 + gs2)
    return 0.15 + 1.9 * g * g
  end

  local kd = d.kind
  if kd == "town" or kd == "chapel" then
    place_buildings(kd == "chapel")
    for i = 1, CS * CS do if kind[i] == K_FREE then kind[i] = K_YARD end end
    scatter(yard_props, K_YARD)
  elseif kd == "cemetery" then
    for i = 1, CS * CS do if kind[i] == K_FREE then kind[i] = K_GRASS end end
    -- gravel paths across, then the fence along the street
    for ly = 0, CS - 1 do
      for lx = 0, CS - 1 do
        if K(lx, ly) == K_GRASS and (lx == 7 or lx == 8 or ly == 8) then kind[ly * CS + lx + 1] = K_PATH end
      end
    end
    -- a mausoleum
    if r() < 0.7 then
      for t = 1, 20 do
        local x, y = irange(r, 1, CS - 6), irange(r, 1, CS - 5)
        local ok = true
        for yy = y, y + 3 do for xx = x, x + 4 do if not freecell(xx, yy, K_GRASS) then ok = false end end end
        if ok then
          for yy = y, y + 3 do for xx = x, x + 4 do take(xx, yy); solid[yy * CS + xx + 1] = yy >= y + 1 end end
          add_obj(ch, "mausoleum", px0 + (x + 2.5) * TS, py0 + (y + 4) * TS - 2)
          add_light(ch, px0 + (x + 2.5) * TS, py0 + (y + 4) * TS + 4, 26, 3, 0.2)
          add_obj(ch, "candles2", px0 + (x + 1) * TS, py0 + (y + 4) * TS + 6)
          break
        end
      end
    end
    for ly = 1, CS - 2, 3 do
      for lx = 1, CS - 2, 3 do
        if freecell(lx, ly, K_GRASS) and r() < 0.75 then
          take(lx, ly)
          local g = pick(r, GRAVES)
          add_obj(ch, g, wx(lx), wy(ly) + 4, nil, { 7, 3 })
          if r() < 0.18 then
            add_obj(ch, r() < 0.5 and "candles" or "candles2", wx(lx) + 8, wy(ly) + 9)
            add_light(ch, wx(lx) + 8, wy(ly) + 6, 30, 4, 0.25, 0.8)
          end
        end
      end
    end
    for k = 1, irange(r, 1, 2) do
      local lx, ly = irange(r, 1, 14), irange(r, 1, 14)
      if freecell(lx, ly, K_GRASS) then take(lx, ly); add_obj(ch, "angel", wx(lx), wy(ly) + 6, nil, { 9, 5 }) end
    end
    scatter({ { "tree3", 0.03, { 5, 3 } }, { "tree", 0.02, { 6, 3 } }, { "bush2", 0.02, { 8, 4 } } }, K_GRASS, grove)
    -- railings where the cemetery meets the pavement, a gap for the paths
    for ly = 0, CS - 1 do
      for lx = 0, CS - 1 do
        local k = K(lx, ly)
        if k == K_GRASS and not used[ly * CS + lx + 1] then
          local n = ly > 0 and K(lx, ly - 1) == K_WALK
          local s = ly < CS - 1 and K(lx, ly + 1) == K_WALK
          local w = lx > 0 and K(lx - 1, ly) == K_WALK
          local e = lx < CS - 1 and K(lx + 1, ly) == K_WALK
          if n or s then
            add_obj(ch, "fence_x", wx(lx), py0 + ly * TS + (n and 3 or 15), nil, { 9, 3 })
          elseif w or e then
            add_obj(ch, "fence_y", px0 + lx * TS + (w and 2 or 14), wy(ly) + 8, nil, { 3, 9 })
          end
        end
      end
    end
  elseif kd == "park" then
    for i = 1, CS * CS do if kind[i] == K_FREE then kind[i] = K_GRASS end end
    for ly = 0, CS - 1 do
      for lx = 0, CS - 1 do
        if K(lx, ly) == K_GRASS and ((lx >= 7 and lx <= 8) or (ly >= 7 and ly <= 8)) then
          kind[ly * CS + lx + 1] = K_PATH
        end
      end
    end
    local cxp, cyp = px0 + 8 * TS, py0 + 8 * TS
    if r() < 0.5 then
      add_obj(ch, "fountain", cxp, cyp + 12, nil, { 34, 10 })
    else
      add_obj(ch, "well", cxp, cyp + 8, nil, { 12, 5 })
    end
    for y = 6, 9 do for x = 5, 10 do take(x, y) end end
    for _, p in ipairs({ { 7, 4 }, { 9, 11 } }) do
      if freecell(p[1], p[2], K_PATH) then take(p[1], p[2]); ch.lampspots[#ch.lampspots + 1] = p end
    end
    scatter({ { "tree", 0.025, { 6, 3 } }, { "tree2", 0.02, { 5, 3 } }, { "tree3", 0.015, { 5, 3 } },
              { "bush", 0.035, { 9, 4 } }, { "bush2", 0.03, { 8, 4 } } }, K_GRASS, grove)
    scatter({ { "bench", 0.03, { 12, 3 } } }, K_PATH)
  elseif kd == "square" or kd == "pyre" or kd == "chapel" then
    -- (the chapel's front is the marble square; see the buildings above)
  end
  if kd == "square" then
    local cxp, cyp = px0 + 8 * TS, py0 + 8 * TS
    if r() < 0.6 or (cx == 0 and cy == 0) then
      add_obj(ch, "fountain", cxp, cyp + 12, nil, { 34, 10 })
    else
      add_obj(ch, "angel", cxp, cyp + 8, nil, { 10, 5 })
    end
    -- a pair of braziers before it and a pair of benches behind, mirrored
    for _, sx in ipairs({ -1, 1 }) do
      local bx, by = cxp + sx * 44, cyp + 45
      if road_at((fdiv(bx, TS)), (fdiv(by, TS)), ne) > 0 then
        add_obj(ch, "brazier", bx, by, nil, { 8, 4 })
        ch.fires[#ch.fires + 1] = { x = bx, y = by - 25, w = 7, rate = 1.2, big = false }
        add_light(ch, bx, by - 8, 62, 6, 1.0)
      end
    end
    if r() < 0.6 then
      for _, sx in ipairs({ -1, 1 }) do add_obj(ch, "bench", cxp + sx * 48, cyp - 40, nil, { 12, 3 }) end
    end
  elseif kd == "pyre" then
    local cxp, cyp = px0 + 8 * TS, py0 + 8 * TS
    add_obj(ch, "pyre", cxp, cyp + 14, nil, { 16, 7 })
    ch.fires[#ch.fires + 1] = { x = cxp, y = cyp + 4, w = 14, rate = 4.0, big = true }
    add_light(ch, cxp, cyp + 4, 112, 7, 1.0, 0.6)
    add_light(ch, cxp, cyp, 72, 7, 1.0, 0.3)
    local spots = {}
    local a0 = irange(r, 0, 5) * PI / 3 + PI / 6
    for k = 0, 5 do
      local a = a0 + k * 2 * PI / 3 + (k >= 3 and PI / 3 or 0)
      local dd = 60
      local ox, oy = cxp + cos(a) * dd, cyp + 14 + sin(a) * dd * 0.7
      local ok = road_at(fdiv(ox, TS), fdiv(oy, TS), ne) > 0 and #spots < 3
      for _, q in ipairs(spots) do
        if abs(q[1] - ox) < 40 and abs(q[2] - oy) < 22 then ok = false end
      end
      if ok then
        spots[#spots + 1] = { ox, oy }
        local name = pick(r, { "coffin", "coffin", "coffin_up", "cage", "barrel" })
        add_obj(ch, name, ox, oy, nil, name == "coffin" and { 14, 4 } or { 8, 4 })
      end
    end
  elseif kd == "chapel" then
    for k = -1, 1, 2 do
      local bx, by = px0 + (8 + k * 3.6) * TS, py0 + 13.6 * TS
      if road_at(fdiv(bx, TS), fdiv(by, TS), ne) > 0 then
        add_obj(ch, "brazier", bx, by, nil, { 8, 4 })
        ch.fires[#ch.fires + 1] = { x = bx, y = by - 25, w = 7, rate = 1.2 }
        add_light(ch, bx, by - 8, 60, 6, 1.0)
      end
    end
    local ax, ay = px0 + 8 * TS, py0 + 13.2 * TS
    if road_at(fdiv(ax, TS), fdiv(ay, TS), ne) > 0 then add_obj(ch, "angel", ax, ay + 8, nil, { 9, 5 }) end
  end

  ------------------------------------------------- street furniture
  -- gas lamps: along a town street in a row on its pavement (both, on an
  -- avenue, half a step apart), every lsp tiles, away from the crossings;
  -- elsewhere here and there
  for _, p in ipairs(ch.lampspots) do p.fixed = true end
  for _, e in ipairs(ne) do
    if e.town then
      local a, b = e.a, e.b
      local u0, u1 = e.dir == 0 and a.x or a.y, e.dir == 0 and b.x or b.y
      for k, side in ipairs(e.lamps) do
        local ph = (e.lph + (k - 1) * e.lsp // 2) % e.lsp
        for u = u0 + 2, u1 - 3 do
          if (u - ph) % e.lsp == 0 then
            local t = (u + 0.5 - u0) / (u1 - u0)
            local c = (e.dir == 0 and a.y or a.x) + ((e.dir == 0 and b.y or b.x) - (e.dir == 0 and a.y or a.x)) * t
            local v = side > 0 and math.ceil(c + e.hw - 0.5) or floor(c - e.hw - 0.5)
            local lx, ly = (e.dir == 0 and u or v) - tx0, (e.dir == 0 and v or u) - ty0
            if t > 0.1 and t < 0.9 and freecell(lx, ly, K_WALK) then
              ch.lampspots[#ch.lampspots + 1] = { lx, ly, fixed = true }
            end
          end
        end
      end
    end
  end
  for ly = 0, CS - 1 do
    for lx = 0, CS - 1 do
      if K(lx, ly) == K_WALK and not used[ly * CS + lx + 1] and h01(tx0 + lx, ty0 + ly, 31) < 0.06 then
        local x, y, town = tx0 + lx + 0.5, ty0 + ly + 0.5, false
        for _, e in ipairs(ne) do
          if e.town and edge_dist(e, x, y) < e.hw + 1.6 then town = true end
        end
        if not town then ch.lampspots[#ch.lampspots + 1] = { lx, ly } end
      end
    end
  end
  local placed = {}
  for _, p in ipairs(ch.lampspots) do
    local ok = true
    for _, q in ipairs(placed) do
      if not (p.fixed and q.fixed) and abs(q[1] - p[1]) + abs(q[2] - p[2]) < 10 then ok = false end
    end
    if ok then
      placed[#placed + 1] = p
      take(p[1], p[2])
      local x, y = wx(p[1]), wy(p[2]) + 4
      local key = key2(tx0 + p[1], ty0 + p[2])
      local o = add_obj(ch, "lamp", x, y, nil, { 4, 2 })
      o.lamp = key
      if lamp_state[key] == nil then lamp_state[key] = h01(tx0 + p[1], ty0 + p[2], 33) < 0.85 end
      ch.lamps[#ch.lamps + 1] = { x = x, y = y, key = key }
    end
  end
  -- odds and ends on the pavements and in the street
  for ly = 0, CS - 1 do
    for lx = 0, CS - 1 do
      if freecell(lx, ly, K_WALK) then
        local v = r()
        local below = ly > 0 and K(lx, ly - 1) == K_HOUSE
        if v < 0.012 and below then
          take(lx, ly); add_obj(ch, pick(r, { "barrel", "crate", "crates" }), wx(lx), wy(ly), nil, { 6, 3 })
        elseif v < 0.016 then
          take(lx, ly); add_obj(ch, "bollard", wx(lx), wy(ly) + 4, nil, { 3, 2 })
        elseif v < 0.022 then
          take(lx, ly); add_obj(ch, "coffin_up", wx(lx), wy(ly), nil, { 7, 3 })
        end
      end
    end
  end
  if kd == "town" and r() < 0.12 then
    -- an abandoned carriage, where the street is wide enough
    for t = 1, 30 do
      local lx, ly = irange(r, 0, CS - 4), irange(r, 1, CS - 2)
      local ok = true
      for yy = ly - 1, ly + 1 do for xx = lx, lx + 3 do if not freecell(xx, yy, K_ROAD) then ok = false end end end
      if ok then
        for yy = ly - 1, ly + 1 do for xx = lx, lx + 3 do take(xx, yy) end end
        add_obj(ch, "carriage", px0 + (lx + 1.6) * TS, wy(ly) + 4, nil, { 34, 6 })
        break
      end
    end
  end
  if kd == "town" and r() < 0.1 then
    for t = 1, 12 do
      local lx, ly = irange(r, 0, CS - 1), irange(r, 0, CS - 1)
      if freecell(lx, ly, K_ROAD) then take(lx, ly); add_obj(ch, "coffin", wx(lx), wy(ly) + 4, nil, { 14, 4 }); break end
    end
  end

  -- a boss's arena: a fifth fewer things in the way (the user's wish), the
  -- ones that make the place (fountain, pyre, lamps, railings...) kept
  if d.boss then
    local keep = { lamp = true, fountain = true, well = true, pyre = true, shrine = true, mausoleum = true,
                   fence_x = true, fence_y = true, brazier = true }
    local cand = {}
    for _, o in ipairs(ch.objs) do
      if o.c and not keep[o.name] then cand[#cand + 1] = o end
    end
    for _, o in ipairs(cand) do o.drop = h01(floor(o.x), floor(o.y), 51) end
    table.sort(cand, function(p, q) return p.drop < q.drop end)
    local gone = {}
    for k = 1, floor(#cand * 0.2 + 0.5) do gone[cand[k]] = true; gone[cand[k].c] = true end
    local objs, cols = {}, {}
    for _, o in ipairs(ch.objs) do if not gone[o] then objs[#objs + 1] = o end end
    for _, c in ipairs(ch.cols) do if not gone[c] then cols[#cols + 1] = c end end
    ch.objs, ch.cols = objs, cols
  end

  ------------------------------------------------- the ground, overlays
  -- the variants of a ground in patches a few tiles wide (a little ragged),
  -- not one at random on every tile; the yards of a district lean to grass
  -- or to earth, in large zones
  local G = GROUND
  local function patch(set, tx, ty, hv)
    local v = sin(tx * 0.33 + ty * 0.12) + sin(ty * 0.27 - tx * 0.17 + 1.7) + ((hv >> 4) % 100 / 100 - 0.5) * 0.5
    return set[min(#set, max(1, floor((v + 2.25) / 4.5 * #set) + 1))]
  end
  local lean = (hash(cx // 2, cy // 2, 43) % 100) / 100 * 1.6 - 0.8
  for ly = 0, CS - 1 do
    for lx = 0, CS - 1 do
      local i = ly * CS + lx + 1
      local k = kind[i]
      local tx, ty = tx0 + lx, ty0 + ly
      local hv = hash(tx, ty, 21)
      if k == K_ROAD then
        local pv = RD(lx, ly)
        local set = pv == PV_SETTS and G.setts or pv == PV_FLAGS and G.flags or pv == PV_ALLEY and G.cobble_moss
          or pv == PV_WARM and G.cobble_warm or pv == PV_MARBLE and G.marble or pv == PV_DARK and G.flags_dark
          or pv == PV_WET and G.cobble_wet or G.cobble
        A[i] = pv == PV_MARBLE and set[(tx + ty) % 2 + 1] or patch(set, tx, ty, hv)
        -- the kerb where the street meets the pavement
        local m = 0
        if RD(lx, ly - 1) == 0 then m = m | 1 end
        if RD(lx + 1, ly) == 0 then m = m | 2 end
        if RD(lx, ly + 1) == 0 then m = m | 4 end
        if RD(lx - 1, ly) == 0 then m = m | 8 end
        if m > 0 and pv ~= PV_MARBLE then
          B[i] = CURB[m]
        elseif (hv >> 8) % 100 < 3 then
          local dv = (hv >> 16) % 100
          local set2 = dv < 30 and DECAL.puddle or dv < 48 and DECAL.leaves or dv < 62 and DECAL.crack
            or dv < 72 and DECAL.drain or dv < 78 and DECAL.manhole or dv < 88 and DECAL.blood
            or dv < 95 and DECAL.straw or DECAL.bones
          B[i] = set2[(hv >> 24) % #set2 + 1]
        end
      elseif k == K_WALK then
        A[i] = patch(G.pave, tx, ty, hv)
        if (hv >> 8) % 100 < 2 then
          local set2 = ((hv >> 16) % 2 == 0) and DECAL.leaves or DECAL.crack
          B[i] = set2[(hv >> 24) % #set2 + 1]
        end
      elseif k == K_HOUSE then
        A[i] = G.dirt[1]                   -- never seen: the house is drawn over it
      elseif k == K_GRASS then
        A[i] = patch(kd == "cemetery" and G.grass_dark or G.grass, tx, ty, hv)
      elseif k == K_PATH then
        A[i] = patch(G.gravel, tx, ty, hv)
      elseif kd == "square" or kd == "pyre" or kd == "chapel" then
        A[i] = patch(G.pave, tx, ty, hv)     -- paved all over: no tile of grass alone in the stones
      else   -- yards: grass or earth in large zones, gravel seldom
        local n = sin(tx * 0.21 + ty * 0.09) + sin(ty * 0.17 - tx * 0.07 + 0.6) + lean + ((hv % 100) / 100 - 0.5) * 0.3
        if n > -0.1 then A[i] = patch(G.grass, tx, ty, hv); kind[i] = K_GRASS
        elseif n > -1.6 then A[i] = patch(G.dirt, tx, ty, hv)
        else A[i] = patch(G.gravel, tx, ty, hv) end
      end
    end
  end
  -- grass spilling over its neighbours (inside the chunk)
  for ly = 0, CS - 1 do
    for lx = 0, CS - 1 do
      local i = ly * CS + lx + 1
      local k = kind[i]
      if k ~= K_GRASS and k ~= K_HOUSE and not B[i] then
        local m = 0
        if ly > 0 and K(lx, ly - 1) == K_GRASS then m = m | 1 end
        if lx < CS - 1 and K(lx + 1, ly) == K_GRASS then m = m | 2 end
        if ly < CS - 1 and K(lx, ly + 1) == K_GRASS then m = m | 4 end
        if lx > 0 and K(lx - 1, ly) == K_GRASS then m = m | 8 end
        if m > 0 then B[i] = GRASS_EDGE[m] end
      end
    end
  end

  -- into the map (layer 1: cells 0-127, layer 2: 128-255)
  local rx0, ry0 = (cx % RING) * CS * 2, (cy % RING) * CS * 2
  for ly = 0, CS - 1 do
    local my = ry0 + ly * 2
    for lx = 0, CS - 1 do
      local i = ly * CS + lx + 1
      local mx = rx0 + lx * 2
      local a, b = A[i] or G.cobble[1], B[i] or 0
      mset(mx, my, a); mset(mx + 1, my, a + 1); mset(mx, my + 1, a + SW8); mset(mx + 1, my + 1, a + SW8 + 1)
      if b > 0 then
        mset(128 + mx, my, b); mset(129 + mx, my, b + 1); mset(128 + mx, my + 1, b + SW8)
        mset(129 + mx, my + 1, b + SW8 + 1)
      else
        mset(128 + mx, my, 0); mset(129 + mx, my, 0); mset(128 + mx, my + 1, 0); mset(129 + mx, my + 1, 0)
      end
    end
  end
  -- a hunter's lamp in the chunks that have one: on the street nearest the middle
  if cx >= 0 and cy >= 0 and cy < AREA then
    local a = cx // AREA
    for k = 1, 2 do
      local lx0, ly0 = lamp_chunk(a, k)
      if lx0 == cx and ly0 == cy then
        local best, bd
        for ly = 2, CS - 3 do
          for lx = 2, CS - 3 do
            local kk = kind[ly * CS + lx + 1]
            if (kk == K_ROAD or kk == K_WALK) and not used[ly * CS + lx + 1] and not solid[ly * CS + lx + 1] then
              local dd = abs(lx - 7.5) + abs(ly - 7.5)
              if not bd or dd < bd then best, bd = { lx, ly }, dd end
            end
          end
        end
        if best then
          local x, y = wx(best[1]), wy(best[2]) + 4
          local key = a * 10 + k
          local o = add_obj(ch, "shrine", x, y, nil, { 8, 4 })
          o.shrine = key
          ch.shrine = { x = x, y = y, key = key, area = a, k = k }
          take(best[1], best[2])
        end
      end
    end
  end
  ch.ready = true
end

local function new_chunk(cx, cy)
  local k = key2(cx, cy)
  local sk = (cy % RING) * RING + (cx % RING)
  local old = slots[sk]
  if old and old ~= k then chunks[old] = nil end
  slots[sk] = k
  local ch = { cx = cx, cy = cy, ready = false, objs = {}, cols = {}, lights = {}, fires = {}, smokes = {},
               lamps = {}, lampspots = {} }
  chunks[k] = ch
  return ch
end

local function chunk(cx, cy) return chunks[key2(cx, cy)] end

-- one chunk at a time is made in the background, a slice per frame
local job, job_ch
local gen_frames = 0

local function finish_job()
  while job and coroutine.status(job) ~= "dead" do
    local ok, err = coroutine.resume(job)
    if not ok then error(err) end
  end
  job, job_ch = nil, nil
end

local function ensure(cx, cy)
  local ch = chunk(cx, cy)
  if ch and ch.ready then return ch end
  if job_ch and job_ch.cx == cx and job_ch.cy == cy then
    finish_job()
    return job_ch or chunk(cx, cy)
  end
  ch = new_chunk(cx, cy)
  gen(ch)
  return ch
end

local cam_x, cam_y = 0, 0

local function stream()
  -- what is on screen has to be there now
  for cy = fdiv(cam_y, CPX), fdiv(cam_y + H - 1, CPX) do
    for cx = fdiv(cam_x, CPX), fdiv(cam_x + W - 1, CPX) do ensure(cx, cy) end
  end
  if job then
    local ok, err = coroutine.resume(job)
    if not ok then error(err) end
    gen_frames = gen_frames + 1
    if coroutine.status(job) == "dead" then job, job_ch = nil, nil end
    return
  end
  -- the next one around the view, nearest first
  local best, bd
  local mx, my = cam_x + W / 2, cam_y + H / 2
  for cy = fdiv(cam_y - MARGIN, CPX), fdiv(cam_y + H + MARGIN, CPX) do
    for cx = fdiv(cam_x - MARGIN, CPX), fdiv(cam_x + W + MARGIN, CPX) do
      local ch = chunk(cx, cy)
      if not (ch and ch.ready) then
        local dx, dy = (cx + 0.5) * CPX - mx, (cy + 0.5) * CPX - my
        local dd = dx * dx + dy * dy
        if not bd or dd < bd then best, bd = { cx, cy }, dd end
      end
    end
  end
  if best then
    job_ch = new_chunk(best[1], best[2])
    job = coroutine.create(gen)
    timeslice(job, 40)
    local ok, err = coroutine.resume(job, job_ch)
    if not ok then error(err) end
    if coroutine.status(job) == "dead" then job, job_ch = nil, nil end
  end
end

----------------------------------------------------------------- the hunter

local DIRS = { [-1] = { [-1] = 5, [0] = 4, [1] = 3 }, [0] = { [-1] = 6, [0] = 0, [1] = 2 },
               [1] = { [-1] = 7, [0] = 0, [1] = 1 } }          -- [dy][dx]: S SE E NE N NW W SW
local DIRV = { { 0, 1 }, { 0.7071, 0.7071 }, { 1, 0 }, { 0.7071, -0.7071 }, { 0, -1 }, { -0.7071, -0.7071 },
               { -1, 0 }, { -0.7071, 0.7071 } }                 -- the same, as steps on the screen
local HP_MAX = 10
-- the hunter: where, which way, the animation playing (HUNT[anim], frame f,
-- ticks ft, played backwards when rev), the action under way (nil: free to
-- walk), the saw cleaver out (ext), health, invulnerable ticks
local ST_MAX = 100
-- rally: health just lost, won back by striking soon (it fades in a while);
-- st: stamina (st_wait: ticks before it comes back); lock: the creature the
-- hunter keeps facing; bt: ticks B is held (a tap dodges, holding runs)
local P = { x = 0, y = 0, dir = 0, anim = "idle", f = 1, ft = 0, rev = false, act = nil, ext = false,
            hp = HP_MAX, inv = 0, combo = 0, queued = false, moving = false, hits = {}, trail = {},
            rally = 0, rally_t = 0, st = ST_MAX, st_wait = 0, lock = nil, bt = 0, brel = 0, l1 = false,
            r1 = false, charge = 0, charged = false, hpmax = HP_MAX, stmax = ST_MAX,
            -- what the paths chosen at the lamps change (none, at first): damage taken, stamina
            -- spent and regained, the pistol and the parry, the open saw, the folded blade's speed
            -- and stamina
            mods = { hurt = 1, st_cost = 1, st_regen = 1, gun = 1, parry = 0, stag = 1, ext_dmg = 1, fold_rate = 1,
                     fold_cost = 1, fold_chain = false } }

local function solid_at(x, y)
  local tx, ty = fdiv(x, TS), fdiv(y, TS)
  if not inside(tx // CS, ty // CS) then return true end      -- the edge of the hunt
  local ch = chunk(tx // CS, ty // CS)
  if not (ch and ch.ready) then return true end
  return ch.solid[(ty % CS) * CS + (tx % CS) + 1]
end

local function blocked(x, y)
  if solid_at(x - 6, y - 3) or solid_at(x + 6, y - 3) or solid_at(x - 6, y + 2) or solid_at(x + 6, y + 2) then
    return true
  end
  -- posts, fountains, graves: of this chunk, and of a neighbour only near its
  -- border (none is wider than 48 pixels)
  local pcx, pcy = fdiv(x, CPX), fdiv(y, CPX)
  local fx, fy = x - pcx * CPX, y - pcy * CPX
  for cy = fy < 48 and pcy - 1 or pcy, fy > CPX - 48 and pcy + 1 or pcy do
    for cx = fx < 48 and pcx - 1 or pcx, fx > CPX - 48 and pcx + 1 or pcx do
      local ch = chunk(cx, cy)
      if ch and ch.ready then
        for _, c in ipairs(ch.cols) do
          local dx = x - c.x
          if dx < 48 and dx > -48 and not c.off then
            dx = dx / (c.rx + 5)
            local dy = (y - c.y) / (c.ry + 3)
            if dx * dx + dy * dy < 1 then return true end
          end
        end
      end
    end
  end
  return false
end

local function place_player()
  -- the start: on a street of the first square, south of its fountain
  ensure(0, 0)
  for rad = 0, 10 do
    for dy = -rad, rad do
      for dx = -rad, rad do
        local x, y = (8 + dx) * TS + 8, (12 + dy) * TS + 8
        if not blocked(x, y) then P.x, P.y = x, y; return end
      end
    end
  end
  P.x, P.y = 8 * TS + 8, 12 * TS + 8
end


----------------------------------------------------------------- particles

local parts = {}
local MAXP = 160
local FLAME = { 0xF8F8D8, 0xF8E890, 0xF8C050, 0xF89030, 0xE06020, 0xA83818, 0x602010 }

-- (flames keep a part of the room free: the rest is for blood, smoke, motes)
local function spawn(x, y, vx, vy, life, kind)
  if #parts >= (kind == 1 and MAXP - 40 or MAXP) then return end
  local p = { x = x, y = y, vx = vx, vy = vy, t = 0, life = life, kind = kind }
  parts[#parts + 1] = p
  return p
end

-- the breakables (see BRK): what is left lies where the thing stood
function BRK.wreck(o)
  o.broken, o.s, o.z, o.col.off = true, SPR[BRK.kinds[o.name]], o.y - 10, true
end
-- broken now: splinters thrown away from the blow (ux, uy), dust, a crack
function BRK.smash_one(o, ux, uy)
  BRK.wreck(o)
  BRK.gone[o.key] = true
  BRK.count = BRK.count + 1
  for _ = 1, 14 do
    local p = spawn(o.x + math.random(-5, 5), o.y - math.random(2, 12), ux * 1.3 + (math.random() - 0.5) * 2.2,
                    uy * 0.6 - 0.8 - math.random() * 1.6, 80 + math.random(70), 8)
    if p then
      p.gy = o.y + math.random(-5, 6)
      p.c = ({ 0x684028, 0x8C6038, 0x4A2C1C, 0xA07848 })[math.random(4)]
    end
  end
  for _ = 1, 5 do
    spawn(o.x + math.random(-6, 6), o.y - math.random(0, 6), (math.random() - 0.5) * 0.6, -0.2, 26 + math.random(16), 3)
  end
  note(3, 150 + math.random(80), 130, NOISE, 130); note(2, 85, 110, SQUARE, 55)
  if o.name == "barrel" then note(1, 640, 90, METAL, 40) end
end
-- every breakable near (x, y), over the chunks round it
function BRK.near(x, y, fn)
  local pcx, pcy = fdiv(x, CPX), fdiv(y, CPX)
  for cy = pcy - 1, pcy + 1 do
    for cx = pcx - 1, pcx + 1 do
      local ch = chunk(cx, cy)
      if ch and ch.ready then
        for _, o in ipairs(ch.objs) do
          if o.col and not o.broken and fn(o) then return o end
        end
      end
    end
  end
end
-- a blow from (x, y) towards (vx, vy): within reach, ahead (cone: the
-- cosine; below -1 all round). Returns how many broke
function BRK.smash(x, y, vx, vy, reach, cone)
  local n = 0
  BRK.near(x, y, function(o)
    local dx, dy = o.x - x, o.y - y
    local dd = sqrt(dx * dx + dy * dy)
    if dd < reach + o.col.rx and (dd < 8 or (dx * vx + dy * vy) / dd > cone) then
      BRK.smash_one(o, dd > 0 and dx / dd or vx, dd > 0 and dy / dd or vy)
      n = n + 1
    end
  end)
  return n
end
-- something (r wide) running into one at (x, y) moving (vx, vy) breaks it
function BRK.touch(x, y, vx, vy, r)
  local hit = BRK.near(x, y, function(o)
    local c = o.col
    local dx, dy = (x - c.x) / (c.rx + (r or 5)), (y - c.y) / (c.ry + (r or 5) * 0.6)
    return dx * dx + dy * dy < 1
  end)
  if hit then
    local d = max(0.01, sqrt(vx * vx + vy * vy))
    BRK.smash_one(hit, vx / d, vy / d)
  end
  return hit
end
-- the first one on a shot's way from (x0, y0) to (x1, y1), and where
function BRK.first(x0, y0, x1, y1)
  local lx, ly = x1 - x0, y1 - y0
  local ll = sqrt(lx * lx + ly * ly)
  for d = 6, ll, 3 do
    local x, y = x0 + lx * d / ll, y0 + ly * d / ll
    local o = BRK.near(x, y, function(o)
      local c = o.col
      local dx, dy = (x - c.x) / (c.rx + 2), (y - c.y) / (c.ry + 3)
      return dx * dx + dy * dy < 1
    end)
    if o then return o, x, y end
  end
end
-- the town fills again: everything whole
function BRK.reset()
  BRK.gone = {}
  for _, ch in pairs(chunks) do
    for _, o in ipairs(ch.objs) do
      if o.broken then o.broken, o.s, o.z, o.col.off = nil, SPR[o.name], o.y, nil end
    end
  end
end

-- a little wind for flames and embers: noise looked up, not drawn every time
local JIT = { k = 0 }
for i = 0, 63 do JIT[i] = (((i * 37 + 11) * 73) % 101 / 100 - 0.5) end

local function update_parts()
  local n = #parts
  local i = 1
  JIT.k = (JIT.k + 13) & 63
  local k0 = JIT.k
  while i <= n do
    local p = parts[i]
    local pt = p.t + 1
    p.t = pt
    if pt >= p.life then
      parts[i] = parts[n]
      parts[n] = nil
      n = n - 1
    else
      p.x = p.x + p.vx
      p.y = p.y + p.vy
      local k = p.kind
      if k == 1 then
        p.vx = p.vx * 0.94 + JIT[(k0 + i * 7) & 63] * 0.12
        p.vy = p.vy * 0.985 - 0.012
      elseif k == 2 then
        p.vx = p.vx + JIT[(k0 + i * 5) & 63] * 0.08
        p.vy = p.vy * 0.995 - 0.004
      elseif k == 3 then
        p.vx = p.vx * 0.99 + 0.004
        p.vy = p.vy * 0.995
      elseif k == 8 then                    -- a splinter: falls, then lies on the street
        if p.y < p.gy then p.vy = p.vy + 0.13 else p.y, p.vx, p.vy = p.gy, 0, 0 end
      elseif k >= 6 then
        p.vx = p.vx * 0.97 + JIT[(k0 + i * 3) & 63] * 0.03
        p.vy = p.vy * 0.99 - 0.002
      else
        p.vy = p.vy + 0.03
      end
      i = i + 1
    end
  end
end

