local function sfx_swing(heavy)
  note(1, heavy and 900 or 1500, heavy and 160 or 110, NOISE, heavy and 70 or 55)
  note(2, heavy and 60 or 90, 120, SAW, 40)
end
local function sfx_shot()
  note(0, 700, 220, NOISE, 200); note(1, 55, 260, SQUARE, 150); note(2, 2600, 90, METAL, 60)
end
local function sfx_clank() note(1, 1800, 160, METAL, 90); note(2, 300, 90, SQUARE, 50) end
local function sfx_hurt() note(1, 110, 260, SAW, 120); note(2, 400, 120, NOISE, 90) end
local function sfx_fall() note(0, 50, 300, NOISE, 160); note(1, 70, 200, SQUARE, 90) end

-- the creatures of the night (filled further down)
local FOE = { list = {}, shots = {}, rings = {}, burns = {}, slain = {}, boss = nil, shake = 0, killed = 0,
              respawns = 0, won = nil, won_t = 0 }
local flash, tracer = 0, nil
local died_t = 0

-- with no direction held, a blow or a shot turns to the target (or the
-- nearest creature)
local function aim_at(range)
  local o = P.lock or FOE.nearest(range)
  if o then P.dir = FOE.dir_to(o.x - P.x, o.y - P.y) end
end

-- stamina: every blow and dodge costs some; it comes back after a pause
-- (wait ticks; a light blow of the folded blade lets the breath come sooner)
local function spend(n, wait)
  P.st, P.st_wait = max(-20, P.st - n * P.mods.st_cost), wait or 30
end

-- the rally: blood taken back from what the blade cuts
local function rally(n)
  local back = min(n, P.rally)
  if back > 0 and P.act ~= "dead" then P.hp, P.rally = min(P.hpmax, P.hp + back), P.rally - back end
end

-- The two forms of the saw cleaver (the user's design). Folded: a little
-- quicker, lighter blows, cheap, the breath back sooner: more blows in less
-- time, more damage over a fight, for harrying and backing off. Open:
-- slower, heavy, dear: the most in one blow (charged above all), a blow
-- landed at the right moment and away. What their blows do (light: the
-- three of a combo; charged: added to the heavy), their stamina, the ticks
-- before the breath comes back, their pace; tests/yharnam/balance.lua
-- measures them.
local BLADE = {
  fold = { light = { 1.5, 1.5, 2.5 }, heavy = 3, charged = 3, trick = 2.5, visceral = 14, cost = 12, heavy_cost = 22,
           trick_cost = 16, breath = 20, rate = 1, reach = 26 },
  open = { light = { 2.5, 2.5, 3.5 }, heavy = 5, charged = 4, trick = 3.5, visceral = 14, cost = 26, heavy_cost = 30,
           trick_cost = 22, breath = 30, rate = 0.95, reach = 34 },
}
-- the form in hand; what its blows do (the open saw: Serrated Oath), cost
-- and how quick they are (the folded blade: Hunter's Path)
function BLADE.form() return P.ext and BLADE.open or BLADE.fold end
function BLADE.dmg(n) return n * (P.ext and P.mods.ext_dmg or 1) end
function BLADE.cost(n) return n * (P.ext and 1 or P.mods.fold_cost) end
function BLADE.rate() return P.ext and BLADE.open.rate or BLADE.fold.rate * P.mods.fold_rate end

local function attack(stage, dx, dy)
  if dx ~= 0 or dy ~= 0 then P.dir = DIRS[dy][dx] else aim_at(44) end
  spend(BLADE.cost(BLADE.form().cost), BLADE.form().breath / BLADE.rate())
  P.act, P.combo, P.queued = "attack", stage, false
  P.trail = {}
  play((P.ext and "xslash" or "slash") .. stage)
end

-- the heavy blow: held at the top while R1 is held, it charges
local function heavy(dx, dy)
  if dx ~= 0 or dy ~= 0 then P.dir = DIRS[dy][dx] else aim_at(44) end
  spend(BLADE.cost(BLADE.form().heavy_cost))
  P.act, P.charge, P.charged, P.queued = "heavy", 0, false, false
  P.trail = {}
  play(xname("heavy"))
end

-- the trick: the saw cleaver transformed in a blow, the combo goes on
local function trick()
  spend(BLADE.cost(BLADE.form().trick_cost))
  P.act, P.combo, P.queued = "trick", min(P.combo + 1, 3), false
  P.trail = {}
  play(P.ext and "trick_x" or "trick")
end

local function sfx_dodge() note(0, 400, 90, NOISE, 50); note(1, 900, 60, NOISE, 30) end

-- B tapped: with a target, a quickstep that way (back: the backstep);
-- without one, a roll; standing still, the backstep
local function dodge(dx, dy)
  spend(P.lock and 15 or 18)
  sfx_dodge()
  local k
  if dx ~= 0 or dy ~= 0 then
    local di = DIRS[dy][dx]
    if P.lock then
      local rel = (di - P.dir) % 8
      k = (rel <= 1 or rel == 7) and "f" or rel == 2 and "l" or rel == 6 and "r" or nil
      if k then
        P.act, P.inv, P.dv = "qstep", 12, DIRV[di + 1]
        play(xname("qstep_" .. k))
        return
      end
    else
      P.dir = di
      P.act, P.inv, P.dv = "roll", 16, DIRV[di + 1]
      play(xname("roll"))
      return
    end
  end
  P.act, P.inv = "backstep", 22
  play(xname("backstep"))
end

-- the visceral attack on a staggered creature
local function visceral(o)
  P.dir = FOE.dir_to(o.x - P.x, o.y - P.y)
  P.act, P.vic, P.inv = "visceral", o, 90
  o.act = "held"
  play(xname("visceral"))
end

local function shoot()
  aim_at(130)
  P.act = "shoot"
  play(xname("shoot"))
end

-- the shot: a flash at the muzzle, a light, a trail to the first wall
local function fire()
  local fr = HUNT[P.anim].d[P.dir + 1][P.f]
  local mx, my = P.x + fr[9], P.y + fr[10]
  local v = DIRV[P.dir + 1]
  -- its way over the street, from the hunter's feet (the muzzle is high and
  -- ahead of him: a creature at arm's length is on the way too) to a wall
  local gx, gy = P.x, P.y
  for k = 1, 60 do
    gx, gy = gx + v[1] * 4, gy + v[2] * 4
    if solid_at(gx, gy) then break end
  end
  local bo, bx, by = BRK.first(P.x, P.y, gx, gy)
  if bo then gx, gy = bx, by end
  local x, y = FOE.shot(P.x, P.y, gx, gy)
  if not x and bo then BRK.smash_one(bo, v[1], v[2]) end
  if not x then x, y = gx, gy + my - P.y end            -- the wall (or what broke), at the muzzle's height
  flash, tracer = 6, { mx, my, x, y, 6 }
  sfx_shot()
  for k = 1, 10 do
    spawn(x, y, (math.random() - 0.5) * 2, (math.random() - 0.5) * 2 - 0.5, 10 + math.random(10), 4)
  end
  spawn(mx, my, v[1] * 0.3, -0.3, 60, 3)
end

-- burnt, struck: hurt (three ways), knocked down, or killed
local function hurt(amount, heavy)
  if P.inv > 0 or P.act == "dead" or P.act == "down" or P.act == "lying" or P.act == "getup" then return end
  amount = amount * P.mods.hurt
  P.rally, P.rally_t = min(P.rally + min(amount, P.hp), P.hpmax), 150
  P.hp = P.hp - amount
  sfx_hurt()
  local now = t
  local recent = 0
  P.hits[#P.hits + 1] = now
  for _, h in ipairs(P.hits) do if now - h < 200 then recent = recent + 1 end end
  if P.hp <= 0 then
    P.hp, P.act, died_t = 0, "dead", 0
    play(xname("death"))
  elseif heavy or recent >= 3 then
    P.hits = {}
    P.act, P.inv = "down", 0
    play(xname("down"))
  else
    P.act, P.inv = "hurt", 50
    play(xname("hurt" .. math.random(3)))
  end
end

----------------------------------------------------------------- the creatures of the night

-- The creatures (FOES, drawn by mkassets.py in 5 directions: SW W NW are SE
-- E NE mirrored) come out of the streets as the town is made around the
-- hunter, a few in every chunk, the kind depending on the district; four
-- bosses wait in the districts of their kind (a pyre, gardens, a cemetery,
-- a chapel). Everything here lives in FOE, so the main chunk keeps few locals.
do
  local list, shots, rings, burns = FOE.list, FOE.shots, FOE.rings, FOE.burns
  local BYNAME = {}
  for _, f in ipairs(FOES) do BYNAME[f.name] = f end
  FOE.byname = BYNAME
  -- how each one fights: hit points, speed, reach of its blows, damage, how
  -- far it sees, its size; heavy blows knock the hunter down
  local STATS = {
    pitchfork = { hp = 5, sp = 0.55, reach = 30, dmg = 2, sight = 110, r = 7 },
    torch = { hp = 5, sp = 0.6, reach = 22, dmg = 2, sight = 120, r = 7, torch = true },
    rifle = { hp = 4, sp = 0.5, reach = 130, dmg = 2, sight = 150, r = 7, ranged = true },
    crone = { hp = 4, sp = 0.55, reach = 18, dmg = 1, sight = 90, r = 6 },
    dog = { hp = 3, sp = 1.35, reach = 24, dmg = 1, sight = 140, r = 8 },
    scourge = { hp = 10, sp = 1.0, reach = 26, dmg = 3, sight = 130, r = 10, heavy = true },
    axehunter = { hp = 8, sp = 0.85, reach = 30, dmg = 2, sight = 140, r = 7 },
    church = { hp = 8, sp = 0.85, reach = 32, dmg = 2, sight = 140, r = 7 },
    kin = { hp = 3, sp = 0.5, reach = 14, dmg = 1, sight = 80, r = 5 },
    brainsucker = { hp = 6, sp = 0.5, reach = 22, dmg = 2, sight = 100, r = 7 },
    lantern = { hp = 5, sp = 0.4, reach = 24, dmg = 2, sight = 90, r = 7, lantern = true },
    spider = { hp = 6, sp = 0.9, reach = 30, dmg = 2, sight = 110, r = 12 },
    butcher = { hp = 60, sp = 0.6, reach = 40, dmg = 3, sight = 160, r = 14 },
    hound = { hp = 50, sp = 1.1, reach = 42, dmg = 3, sight = 170, r = 18 },
    father = { hp = 55, sp = 0.85, reach = 34, dmg = 3, sight = 170, r = 9 },
    watcher = { hp = 65, sp = 0.6, reach = 44, dmg = 3, sight = 180, r = 14 },
  }
  FOE.stats = STATS
  -- who lives where, and the boss of each kind of district
  local POOL = {
    town = { "pitchfork", "torch", "rifle", "crone", "pitchfork", "torch", "dog" },
    square = { "pitchfork", "torch", "crone", "rifle" },
    pyre = { "torch", "torch", "pitchfork", "crone" },
    park = { "dog", "dog", "scourge" },
    cemetery = { "axehunter", "church", "lantern", "dog" },
    chapel = { "kin", "brainsucker", "lantern", "spider", "church", "kin" },
  }
  local BOSS_OF = { pyre = "butcher", park = "hound", cemetery = "father", chapel = "watcher" }
  FOE.boss_of = BOSS_OF
  local MAXF = 14

  local function dir_to(dx, dy)
    return (2 - floor(math.atan(dy, dx) / (PI / 4) + 0.5)) % 8
  end
  FOE.dir_to = dir_to

  -- the frame on screen: the drawn direction, mirrored for SW W NW
  local function frame(o)
    local d = o.dir
    return o.def.a[o.anim].d[d <= 4 and d + 1 or 9 - d][o.f], d > 4
  end
  FOE.frame = frame
  local function point(o, k)
    local fr, flip = frame(o)
    local px, py = fr[5 + 2 * k], fr[6 + 2 * k]
    return o.x + (flip and -px or px), o.y + py
  end
  FOE.point = point

  local function play(o, name)
    o.anim, o.f, o.ft, o.newf = name, 1, 0, true
  end
  FOE.play = play
  -- one tick (rate ticks); true when a one-shot animation has ended
  local function step(o, rate)
    local a = o.def.a[o.anim]
    o.newf = false
    o.ft = o.ft + (rate or 1)
    if o.ft >= a.t[o.f] then
      if o.f < #a.t then o.f, o.ft, o.newf = o.f + 1, 0, true
      elseif a.loop then o.f, o.ft, o.newf = 1, 0, true
      else return true end
    end
    return false
  end
  FOE.step = step
  local function has(list_, f)
    if not list_ then return false end
    for _, v in ipairs(list_) do if v == f then return true end end
    return false
  end

  -- what each one leaves when slain: blood echoes
  local ECHOES = { pitchfork = 30, torch = 30, rifle = 40, crone = 25, dog = 20, scourge = 80, axehunter = 120,
                   church = 120, kin = 50, brainsucker = 90, lantern = 70, spider = 80, butcher = 800,
                   hound = 1000, father = 1200, watcher = 1400 }
  FOE.echoes = ECHOES

  -- area: the deeper in the hunt, the stronger (more health, harder blows)
  local function new(name, x, y, home, area)
    local def = BYNAME[name]
    local st = STATS[name]
    area = area or 0
    if area > 0 then
      st = setmetatable({ hp = floor(st.hp * (1 + 0.35 * area)), dmg = st.dmg + area // 2 }, { __index = st })
    end
    local o = { def = def, st = st, name = name, x = x, y = y, dir = 0, hp = st.hp, cd = 30 + math.random(60),
                area = area, hpmax = st.hp, ph = 1, style = FOE.style_of(name, 1), side = math.random(2) * 2 - 3,
                agg = def.boss and 1 or 1 + 0.08 * area, back = 0, react_cd = 0, chained = 0,
                boss = def.boss, home = home, hx = x, hy = y, alert = false, corpse = 0, z = y }
    play(o, "idle")
    o.f = math.random(#def.a.idle.t)
    list[#list + 1] = o
    return o
  end
  FOE.new = new

  -- the foot of a creature on the street: walls, houses and posts stop it
  local function stuck(x, y, r)
    local q = min(r, 8) * 0.6
    local tx0, tx1, ty0, ty1 = fdiv(x - q, TS), fdiv(x + q, TS), fdiv(y - 2, TS), fdiv(y + 2, TS)
    local ch
    for ty = ty0, ty1 do
      for tx = tx0, tx1 do
        ch = chunk(tx // CS, ty // CS)
        if not (ch and ch.ready) or ch.solid[(ty % CS) * CS + tx % CS + 1] or not inside(tx // CS, ty // CS) then
          return true
        end
      end
    end
    for _, c in ipairs(ch.cols) do
      local dx = x - c.x
      if dx < 24 and dx > -24 and not c.off then
        dx = dx / (c.rx + 3)
        local dy = (y - c.y) / (c.ry + 2)
        if dx * dx + dy * dy < 1 then return true end
      end
    end
    return false
  end
  local function move(o, vx, vy)
    local r = o.st.r
    local nx, ny = o.x + vx, o.y + vy
    if o.boss then BRK.touch(nx, ny, vx, vy, r) end      -- a boss goes through barrels and crates
    if not stuck(nx, ny, r) then
      o.x, o.y = nx, ny
    elseif not stuck(nx, o.y, r) then
      o.x = nx
    elseif not stuck(o.x, ny, r) then
      o.y = ny
    end
  end

  -- a chunk made off screen gets its creatures (once; again after a death)
  local function populate(ch)
    ch.spawned = true
    local cx, cy = ch.cx, ch.cy
    if abs(cx) + abs(cy) <= 1 or not inside(cx, cy) then return end     -- the first streets are quiet
    local d = district(cx, cy)
    local area = cx // AREA
    local r = newrng(hash(cx, cy, 23 + FOE.respawns))
    local pool = POOL[d.kind] or POOL.town
    local n = d.kind == "town" and irange(r, 0, 2) or irange(r, 1, 3)
    if ch.shrine then n = min(n, 1) end                 -- a little peace by a hunter's lamp
    local function spot()
      for _ = 1, 16 do
        local lx, ly = irange(r, 1, CS - 2), irange(r, 1, CS - 2)
        local k = ch.kind[ly * CS + lx + 1]
        local x, y = (cx * CS + lx) * TS + 8, (cy * CS + ly) * TS + 8
        if (k == K_ROAD or k == K_WALK or k == K_FREE) and not ch.solid[ly * CS + lx + 1] and not stuck(x, y, 8) then
          return x, y
        end
      end
    end
    for _ = 1, n do
      if #list >= MAXF then break end
      local x, y = spot()
      if x then new(pick(r, pool), x, y, key2(cx, cy), area) end
    end
    -- the boss, in the arena at the end of the area, until it is slain
    local bn = d.boss and BOSS_OF[d.kind]
    local key = key2(cx, cy)
    if bn and not FOE.slain[key] then
      for _, o in ipairs(list) do if o.boss and o.home == key then return end end
      local x, y
      for rad = 0, 5 do
        for _ = 1, 8 do
          local lx, ly = 8 + irange(r, -rad, rad), 8 + irange(r, -rad, rad)
          local k = ch.kind[ly * CS + lx + 1]
          local px, py = (cx * CS + lx) * TS + 8, (cy * CS + ly) * TS + 8
          if k ~= K_HOUSE and not ch.solid[ly * CS + lx + 1] and not stuck(px, py, 12) then x, y = px, py; break end
        end
        if x then break end
      end
      if x then new(bn, x, y, key, area) end
    end
  end
  FOE.populate = populate

  local function on_screen_chunk(ch)
    local x0, y0 = ch.cx * CPX, ch.cy * CPX
    return x0 < cam_x + W + 24 and x0 + CPX > cam_x - 24 and y0 < cam_y + H + 24 and y0 + CPX > cam_y - 24
  end
  function FOE.spawn_around()
    if FOE.quiet then return end                  -- (the tests on the PC)
    for cy = fdiv(cam_y - MARGIN, CPX), fdiv(cam_y + H + MARGIN, CPX) do
      for cx = fdiv(cam_x - MARGIN, CPX), fdiv(cam_x + W + MARGIN, CPX) do
        local ch = chunk(cx, cy)
        if ch and ch.ready and not ch.spawned and not on_screen_chunk(ch) then populate(ch) end
      end
    end
  end

  ----------------------------------------------------------- sounds
  local function sfx_thud() note(1, 90, 120, NOISE, 110); note(2, 160, 80, SQUARE, 50) end
  local function sfx_cry(o)
    local k = o.def.kind
    if k == "beast" then note(3, 180, 220, SAW, 70); note(2, 120, 260, NOISE, 50)
    elseif k == "horror" then note(3, 900, 300, TRIANGLE, 50); note(2, 1340, 300, TRIANGLE, 30)
    else note(3, 220, 200, SAW, 50) end
  end
  local function sfx_roar() note(0, 60, 700, SAW, 120); note(1, 45, 800, NOISE, 110); note(2, 90, 600, SQUARE, 60) end
  local function sfx_boom() note(0, 40, 500, NOISE, 200); note(1, 55, 400, SQUARE, 120) end

  ----------------------------------------------------------- the hunter hits them
  local function bleed(o, n)
    for _ = 1, n do
      spawn(o.x + (math.random() - 0.5) * 6, o.y - 10 - math.random(8), (math.random() - 0.5) * 2.2,
            -math.random() * 1.6, 18 + math.random(16), 5)
    end
  end
  -- staggered: reeling, open to a visceral attack for a while
  local function stagger(o, ticks)
    o.act, o.beam, o.stag = "stagger", nil, ticks or 110
    o.hold, o.queue, o.next = nil, nil, nil
    play(o, "hurt")
    note(1, 2400, 140, METAL, 70); note(2, 1200, 220, TRIANGLE, 60)
  end
  FOE.stagger = stagger

  -- damage to a creature; flinch: the blow (or the shot) stops what it does.
  -- A boss flinches only when the blows add up (its poise breaks)
  local function harm(o, dmg, flinch)
    if o.act == "dead" then return end
    o.hp = o.hp - dmg
    o.alert = true
    bleed(o, 6 + dmg * 3)
    sfx_thud()
    if o.boss and not o.awake then o.awake = true; FOE.boss = o end
    local reeling = o.act == "stagger" or o.act == "held"
    if o.boss and o.hp > 0 and not reeling then
      o.poise = (o.poise or 0) + dmg
      if o.poise >= 16 then
        o.poise = 0
        stagger(o, 80)
        return
      end
    end
    if o.hp <= 0 then
      o.act, o.corpse, o.ended = "dead", 0, false
      play(o, "death")
      sfx_cry(o)
      FOE.killed = FOE.killed + 1
      local e = floor(ECHOES[o.name] * (1 + 0.5 * o.area))
      G.echoes = G.echoes + e
      G.popups[#G.popups + 1] = { x = o.x, y = o.y - 30, t = 60, s = "+" .. e }
      if o.boss then
        FOE.slain[o.home] = true
        FOE.won, FOE.won_t = o.def.title, 0
        if FOE.boss == o then FOE.boss = nil end
        G.open = max(G.open, o.area + 2)        -- the way on, to the next area
        sfx_roar()
      end
    elseif flinch and not reeling then
      o.act, o.beam, o.hold, o.queue, o.next = "hurt", nil, nil, nil, nil
      play(o, "hurt")
    end
  end
  FOE.harm = harm

  -- the nearest living creature within range of the hunter
  function FOE.nearest(range)
    local best, bd = nil, range * range
    for _, o in ipairs(list) do
      if o.act ~= "dead" then
        local dx, dy = o.x - P.x, o.y - P.y
        local d2 = dx * dx + dy * dy
        if d2 < bd then best, bd = o, d2 end
      end
    end
    return best
  end

  -- a blow of the saw cleaver: every creature in reach, ahead of the hunter.
  -- A charged blow in the back staggers (then comes the visceral attack)
  function FOE.strike(dmg, reach, cone, charged)
    local v = DIRV[P.dir + 1]
    BRK.smash(P.x, P.y, v[1], v[2], reach, cone)
    local n = 0
    for _, o in ipairs(list) do
      if o.act ~= "dead" and o.act ~= "held" then
        local dx, dy = o.x - P.x, o.y - P.y
        local dd = sqrt(dx * dx + dy * dy)
        if dd < reach + o.st.r and (dd < 6 or (dx * v[1] + dy * v[2]) / dd > cone) then
          local f = DIRV[o.dir + 1]
          local behind = dd > 1 and (f[1] * dx + f[2] * dy) / dd > 0.35   -- it faces away from the hunter
          harm(o, dmg, not o.boss)
          if charged and behind and o.act ~= "dead" then stagger(o, 110 * P.mods.stag) end
          n = n + 1
        end
      end
    end
    return n
  end

  -- a staggered creature right ahead of the hunter: the visceral attack
  function FOE.visceral_target()
    local v = DIRV[P.dir + 1]
    for _, o in ipairs(list) do
      if o.act == "stagger" then
        local dx, dy = o.x - P.x, o.y - P.y
        local dd = sqrt(dx * dx + dy * dy)
        if dd < 24 + o.st.r * 0.6 and (dd < 10 or (dx * v[1] + dy * v[2]) / dd > 0.2) then return o end
      end
    end
  end
  -- the hand torn out: a great wound, a fountain of blood
  function FOE.visceral(o, dmg)
    o.act, o.stag = nil, 0
    bleed(o, 40)
    note(0, 70, 400, SAW, 150); note(1, 300, 260, NOISE, 140)
    FOE.shake = 8
    harm(o, dmg, true)
  end
  -- the shot, over the street from (x0, y0) to (x1, y1): the first creature
  -- on its way (where it is hit: its chest). One caught winding up a blow
  -- is staggered (as the hunters parry with their guns)
  function FOE.shot(x0, y0, x1, y1)
    local best, bt
    local lx, ly = x1 - x0, y1 - y0
    local ll = lx * lx + ly * ly
    if ll < 1 then return nil end
    for _, o in ipairs(list) do
      if o.act ~= "dead" then
        local tt = ((o.x - x0) * lx + (o.y - y0) * ly) / ll
        if tt > 0 and tt <= 1 then
          local ex, ey = o.x - (x0 + lx * tt), o.y - (y0 + ly * tt)
          if ex * ex + ey * ey < (o.st.r + 6) ^ 2 and (not bt or tt < bt) then best, bt = o, tt end
        end
      end
    end
    if best then
      local o = best
      local a = o.act and o.def.a[o.anim]
      local hits = a and (a.hit or a.fire or a.slam or a.beam)
      local winding = false
      if hits and o.act ~= "hurt" and o.act ~= "stagger" and o.act ~= "held" then
        -- the ticks into its blow, against the tick it lands (and after, as the paths grant)
        local el, due = o.ft, 0
        for k = 1, o.f - 1 do el = el + a.t[k] end
        for k = 1, hits[1] - 1 do due = due + a.t[k] end
        winding = el < due + P.mods.parry
      end
      harm(o, P.mods.gun, not o.boss)
      if winding and o.act ~= "dead" then stagger(o, 110 * P.mods.stag) end      -- the parry
      return o.x, o.y - 12
    end
  end

  ----------------------------------------------------------- they hit the hunter
  local function reach_player(o, reach, cone)
    local dx, dy = P.x - o.x, P.y - o.y
    local dd = sqrt(dx * dx + dy * dy)
    if dd > reach + 6 then return false end
    if dd < 8 then return true end
    local v = DIRV[o.dir + 1]
    return (dx * v[1] + dy * v[2]) / dd > (cone or 0.3)
  end
  local function ring(x, y, rmax, dmg, heavy, c)
    rings[#rings + 1] = { x = x, y = y, r = 2, rmax = rmax, dmg = dmg, heavy = heavy, c = c or 0xC8B898, hit = false }
    if dmg > 0 then BRK.smash(x, y, 0, 0, rmax * 0.8, -2) end
  end

  -- what happens on the frames that matter: blows, shots, bombs, slams
  local function event(o)
    local a = o.def.a[o.anim]
    local f = o.f
    local st = o.st
    if has(a.hit, f) then
      local reach, cone = st.reach, 0.3
      if o.anim == "whirl" then reach, cone = 40, -1 end
      if o.anim == "combo1" and o.name == "watcher" then cone = -0.2 end
      if reach_player(o, reach, cone) then hurt(o.boss and 3 or st.dmg, st.heavy or (o.boss and f == a.hit[#a.hit] and
                                                                                    math.random() < 0.4)) end
      local v = DIRV[o.dir + 1]
      BRK.smash(o.x, o.y, v[1], v[2], reach, cone)
      note(1, o.boss and 600 or 1100, 110, NOISE, o.boss and 80 or 50)
    end
    if has(a.fire, f) then
      local mx, my = point(o, 2)
      FOE.flash = { mx, my, 6 }
      note(0, 600, 220, NOISE, 180); note(1, 70, 200, SQUARE, 110)
      if o.name == "father" then
        -- the blunderbuss: a spray of shot, close and wide
        local dx, dy = P.x - o.x, P.y - o.y
        local dd = sqrt(dx * dx + dy * dy)
        local v = DIRV[o.dir + 1]
        if dd < 80 and (dd < 8 or (dx * v[1] + dy * v[2]) / dd > 0.72) then hurt(3, dd < 40) end
        for _ = 1, 14 do
          local sp = 2 + math.random() * 2
          local an = math.atan(v[2], v[1]) + (math.random() - 0.5) * 0.9
          spawn(mx, my, cos(an) * sp, sin(an) * sp, 12 + math.random(10), 4)
        end
      else
        -- the rifle: a ball that flies until it hits
        local dx, dy = P.x - o.x, P.y - o.y
        local dd = max(1, sqrt(dx * dx + dy * dy))
        shots[#shots + 1] = { x = o.x, y = o.y, h = o.y - my, vx = dx / dd * 3.4, vy = dy / dd * 3.4, t = 70,
                              kind = "ball", dmg = st.dmg }
      end
    end
    if has(a.throw, f) then
      local hx, hy = point(o, 2)
      local tx, ty = P.x + (math.random() - 0.5) * 16, P.y + (math.random() - 0.5) * 10
      shots[#shots + 1] = { x = o.x, y = o.y, h = o.y - hy, x0 = o.x, y0 = o.y, h0 = o.y - hy, tx = tx, ty = ty,
                            t = 0, T = 42, kind = "bomb" }
      note(2, 300, 200, NOISE, 60)
    end
    if has(a.slam, f) then
      local sx, sy = o.x, o.y
      if o.name == "butcher" then sx, sy = point(o, 1); sy = sy + 24 end
      if o.name == "hound" then
        local v = DIRV[o.dir + 1]
        sx, sy = o.x + v[1] * 32, o.y + v[2] * 32
      end
      ring(sx, sy, o.name == "watcher" and 74 or 62, 3, true)
      FOE.shake = 14
      sfx_boom()
      for _ = 1, 16 do
        local an = math.random() * 2 * PI
        spawn(sx + cos(an) * 6, sy + sin(an) * 4, cos(an) * 1.2, sin(an) * 0.7 - 0.4, 20 + math.random(14), 3)
      end
    end
    if has(a.howl, f) then
      ring(o.x, o.y, 110, 0, false, 0xA0A8B8)
      FOE.shake = 24
      o.fury = 420
      sfx_roar()
    end
    if has(a.beam, f) then
      local ex, ey = point(o, 2)
      o.beam = { ex = ex, ey = ey, tx = P.x, ty = P.y - 10, t = 70 }
      note(0, 1400, 900, TRIANGLE, 60); note(1, 1880, 900, TRIANGLE, 40)
    end
  end

  ----------------------------------------------------------- how each one fights
  -- Not a count of blows only (the user's wish): every kind has its ways.
  -- keep: the distance it holds between blows; orbit: it circles the hunter
  -- there (the side changes now and then); zig: it zigzags as it comes;
  -- stalk: it comes slower; flee: it backs away when the hunter is closer;
  -- rush: its pace as it closes in to strike; wait: ticks between its blows;
  -- wind: the pace of its wind-up (below 1: slower, easier to read and to
  -- parry); hold: the chance of a blow held at the top (a delayed blow, its
  -- weapon glints) and for how many ticks; quick: the chance of a blow with
  -- no wind-up to speak of; strike: the pace of the blow and what follows
  -- (below 1: a long recovery, a window); chain: the chance of another blow
  -- at once (at most chains; tired: its rest after them); lunge: its step in
  -- the wind-up; back: ticks it backs off after a blow; react: the chance it
  -- steps away from the hunter's blow; punish: it strikes at once when the
  -- hunter is caught in his own blow
  local AI = {}
  AI.STYLE = {
    pitchfork = { keep = 34, wait = { 60, 110 }, wind = 0.85, hold = { 0.5, 14, 26 }, chain = 0.2, chains = 1,
                  lunge = 0.4 },                                        -- wary: the fork's length, a slow thrust
    torch = { keep = 20, rush = 1.6, wait = { 25, 50 }, wind = 1.2, chain = 0.5, chains = 2, lunge = 0.4 },  -- reckless
    rifle = { keep = 100, flee = 64, wait = { 80, 140 }, hold = { 1, 20, 40 } },  -- aims long, from afar
    crone = { keep = 30, zig = 0.7, stalk = 0.8, rush = 1.8, wait = { 35, 70 }, wind = 1.3, lunge = 0.9, back = 30,
              react = 0.4 },                                            -- erratic: darts in and away
    dog = { keep = 50, orbit = 1, rush = 1.2, wait = { 25, 50 }, back = 18, react = 0.35, lunge = 1.4 },  -- bite, away
    scourge = { keep = 22, rush = 1.4, wait = { 20, 40 }, wind = 1.1, strike = 0.8, chain = 0.7, chains = 2,
                lunge = 0.5, tired = 70 },                              -- a frenzy, then spent
    axehunter = { keep = 48, orbit = 0.7, rush = 1.7, wait = { 45, 80 }, hold = { 0.6, 10, 22 }, chain = 0.35,
                  chains = 1, lunge = 0.8, react = 0.5, punish = true },  -- a duellist
    church = { keep = 30, orbit = 0.4, wait = { 50, 90 }, wind = 0.9, hold = { 0.75, 24, 44 }, quick = 0.25,
               lunge = 0.3 },                                           -- the delayed blow, or a quick one
    kin = { keep = 14, zig = 0.9, rush = 1.3, wait = { 15, 35 }, wind = 1.2, chain = 0.3, chains = 1,
            back = 10 },                                                -- a swarm
    brainsucker = { keep = 24, stalk = 0.6, wait = { 40, 80 }, wind = 0.7, lunge = 0.2 },  -- stalks, a slow grasp
    lantern = { keep = 44, stalk = 0.7, rush = 0.8, wait = { 90, 150 }, wind = 0.7, strike = 0.7 },  -- creeps, slow
    spider = { keep = 80, orbit = 0.6, rush = 2.2, wait = { 50, 90 }, back = 40, lunge = 0.9, react = 0.3 },  -- darts
  }
  -- The bosses: three phases as their blood runs out (above two thirds,
  -- above one third, the last), plain at first, quicker and crueller at the
  -- end. rate: the pace of every move; near (in reach), mid (to 90 px), far:
  -- its moves by weight, "a+b" a pattern (b at once after a; it comes after
  -- the hunter for b), "" a few steps closer. A new phase begins with a
  -- roar (the hound howls): a moment to strike
  AI.BOSS = {
    butcher = {
      { rate = 0.9, wait = { 70, 110 }, hold = { 0.5, 12, 22 }, keep = 36,
        near = { "attack", 6, "combo1", 3 }, mid = { "throw", 2, "", 3 }, far = { "throw", 2, "", 2 } },
      { rate = 1, wait = { 45, 80 }, hold = { 0.35, 10, 24 }, keep = 36,
        near = { "attack", 2, "combo1", 3, "combo2", 3, "slam", 2 },
        mid = { "slam", 3, "throw", 2, "throw+slam", 2, "", 2 }, far = { "throw", 3, "", 2 } },
      { rate = 1.15, wait = { 25, 50 }, hold = { 0.25, 20, 34 }, keep = 30, rush = 1.5,
        near = { "combo1+slam", 3, "combo2+combo1", 3, "attack+combo2", 2, "slam", 1 },
        mid = { "slam+combo1", 3, "throw+throw", 2, "", 1 }, far = { "throw+throw", 2, "", 2 } },
    },
    hound = {
      { rate = 1, wait = { 50, 90 }, keep = 70, orbit = 0.8,
        near = { "attack", 4, "combo1", 2 }, mid = { "pounce", 4, "", 2 }, far = { "", 1 } },
      { rate = 1.1, wait = { 35, 60 }, keep = 64, orbit = 1, react = 0.3,
        near = { "attack", 2, "combo1", 3, "combo2", 3 }, mid = { "pounce", 3, "pounce+combo2", 3 },
        far = { "howl", 1, "", 2 } },
      { rate = 1.1, wait = { 25, 45 }, keep = 50, orbit = 1.2, react = 0.3, fury = true,
        near = { "combo1+combo2", 3, "combo2+pounce", 2, "attack+combo1", 2 },
        mid = { "pounce+combo1", 4, "pounce+pounce", 2 }, far = { "pounce", 2, "", 1 } },
    },
    father = {
      { rate = 1, wait = { 55, 90 }, hold = { 0.4, 10, 20 }, keep = 44, orbit = 0.7, react = 0.3,
        near = { "attack", 4, "combo1", 3 }, mid = { "blast", 4, "", 2 }, far = { "", 1 } },
      { rate = 1.1, wait = { 40, 70 }, hold = { 0.3, 10, 24 }, keep = 40, orbit = 0.9, react = 0.35, punish = true,
        near = { "combo1", 3, "combo2", 3, "whirl", 2, "combo1+blast", 2 },
        mid = { "blast", 3, "blast+combo1", 2, "", 1 }, far = { "", 1 } },
      { rate = 1.25, wait = { 15, 35 }, keep = 30, rush = 1.5, punish = true,
        near = { "whirl+combo2", 3, "combo1+whirl", 3, "combo2+blast", 2 },
        mid = { "blast+combo1", 3, "blast+whirl", 2, "", 1 }, far = { "", 1 } },
    },
    watcher = {
      { rate = 0.9, wait = { 70, 110 }, keep = 90, flee = 50,
        near = { "attack", 3, "grasp", 2 }, mid = { "grasp", 3, "beam", 2 }, far = { "beam", 3 } },
      { rate = 1, wait = { 45, 80 }, keep = 70,
        near = { "attack", 2, "combo1", 3, "combo2", 3, "grasp", 2 }, mid = { "beam+grasp", 3, "grasp", 2 },
        far = { "beam", 3, "", 1 } },
      { rate = 1.15, wait = { 25, 45 }, keep = 50, orbit = 0.6,
        near = { "combo1+grasp", 3, "combo2+combo1", 3, "attack+grasp", 2 },
        mid = { "grasp+combo2", 3, "beam+grasp", 2 },
        far = { "beam+beam", 2, "", 1 } },
    },
  }
  FOE.styles, FOE.bosses = AI.STYLE, AI.BOSS
  function FOE.style_of(name, ph) return AI.BOSS[name] and AI.BOSS[name][ph] or AI.STYLE[name] end
  -- how far the moves of the bosses reach (the others: the reach of its blow)
  AI.RANGE = { throw = 150, blast = 76, pounce = 120, howl = 999, beam = 170, grasp = 80, slam = 64, whirl = 44 }
  -- the patterns taken apart, once
  AI.SEQ = {}
  function AI.seq(m)
    local q = AI.SEQ[m]
    if not q then
      q = {}
      for w in m:gmatch("[^+]+") do q[#q + 1] = w end
      AI.SEQ[m] = q
    end
    return q
  end
  -- the first frame of every move where something happens (a blow, a shot)
  AI.FIRST = {}
  function AI.init()
    for _, f in ipairs(FOES) do
      for _, a in pairs(f.a) do
        for k, v in pairs(a) do
          if k ~= "t" and k ~= "d" and k ~= "loop" and k ~= "shift" and (not AI.FIRST[a] or v[1] < AI.FIRST[a]) then
            AI.FIRST[a] = v[1]
          end
        end
      end
    end
  end
  AI.init()
  FOE.ai = AI
  function AI.pick(l)
    if not l then return nil end
    local sum = 0
    for i = 2, #l, 2 do sum = sum + l[i] end
    local r = math.random() * sum
    for i = 1, #l, 2 do
      r = r - l[i + 1]
      if r <= 0 then return l[i] end
    end
    return l[#l - 1]
  end

  -- a move begins: a blow held at the top or a quick one is decided here
  function AI.start(o, name, dd)
    local S = o.style
    o.act, o.hold = name, nil
    o.quick = (S.quick and math.random() < S.quick) or (S.flee and dd < S.flee * 0.7) or nil
    play(o, name)
  end
  FOE.start = AI.start

  -- what a boss does next, from how far the hunter is and its phase
  function AI.choice(o, dd)
    local S = o.style
    return AI.pick(dd < o.st.reach + 10 and S.near or dd < 90 and S.mid or S.far)
  end

  -- a step; blocked, it slides along the wall on its side (or turns to the other)
  function AI.slide(o, vx, vy)
    local x0, y0 = o.x, o.y
    move(o, vx, vy)
    if o.x == x0 and o.y == y0 then
      local s = o.side
      move(o, -vy * s, vx * s)
      if o.x == x0 and o.y == y0 then o.side = -s end
    end
  end

  -- on its way (k: its pace), towards (dx, dy) or away
  function AI.go(o, dx, dy, dd, k)
    local f = o.fury and 1.5 or 1
    local sp = o.st.sp * k * f
    local vx, vy = dx / dd * sp, dy / dd * sp
    local z = o.style.zig
    if z then
      local w = sin(t * 0.12 + o.hx) * z
      vx, vy = vx - vy * w, vy + vx * w
    end
    AI.slide(o, vx, vy)
    if o.anim ~= "walk" then play(o, "walk") end
    step(o, k * f * (o.name == "dog" and 1.2 or 1))
  end

  ----------------------------------------------------------- every tick
  local function think(o, alive)
    local st, S = o.st, o.style
    local dx, dy = P.x - o.x, P.y - o.y
    local dd = max(0.01, sqrt(dx * dx + dy * dy))
    if o.act == "dead" then
      if not o.ended then
        o.ended = step(o)
        if o.newf and o.f == 4 then note(0, 50, 200, NOISE, 90) end
      end
      o.corpse = o.corpse + 1
      return
    end
    if o.act == "stagger" then
      if o.f < 2 then step(o) end                 -- reeling: held on the second frame of its hurt
      o.stag = o.stag - 1
      if o.stag <= 0 then
        o.act, o.cd = nil, 30
        play(o, "idle")
      end
      return
    end
    if o.act == "held" then                       -- in the hunter's grip
      if P.vic ~= o then o.act, o.stag = "stagger", 20 end
      return
    end
    if o.act == "rage" then                       -- a boss into its next phase: it reels and roars
      if o.f < 2 then step(o, 0.25) end
      o.rage = o.rage - 1
      if o.rage <= 0 then
        o.act, o.cd = nil, 10
        play(o, "idle")
      end
      return
    end
    if o.act then
      if o.hold and o.hold > 0 then o.hold = o.hold - 1 return end    -- the blow held at the top
      local a = o.def.a[o.anim]
      local first = AI.FIRST[a]
      local pre = first and o.f < first
      local rate = o.act == "hurt" and 1 or (S.rate or 1) * o.agg * (o.fury and 1.25 or 1) *
                   (pre and (o.quick and 1.4 or S.wind or 1) or S.strike or 1)
      local done = step(o, rate)
      if o.newf then
        if pre and o.f == first - 1 and not o.quick and S.hold and math.random() < S.hold[1] then
          o.hold = S.hold[2] + math.random(0, S.hold[3] - S.hold[2])
        end
        event(o)
      end
      -- a few creatures lunge in their blow (the pounce flies in its frames)
      if (o.anim == "attack" or o.anim:sub(1, 5) == "combo") and a.hit and o.f <= a.hit[1] and dd > st.r + 8 then
        local v = DIRV[o.dir + 1]
        local k = S.lunge or 0.3
        move(o, v[1] * k, v[2] * k)
      end
      if done then
        -- the body ends ahead of where it stood (a pounce): it is there now
        local sh = a.shift
        if sh then
          local v = DIRV[o.dir + 1]
          move(o, v[1] * sh, v[2] * sh)
        end
        local was = o.act
        o.act = nil
        play(o, "idle")
        local nxt = o.queue and table.remove(o.queue, 1)
        if o.queue and #o.queue == 0 then o.queue = nil end
        if nxt then
          o.next, o.cd, o.chase = nxt, 4 + math.random(8), 0          -- the pattern goes on
        elseif was == "hurt" then
          o.cd = max(o.cd, 20 + math.random(20))
        elseif S.chain and was == "attack" and o.chained < (S.chains or 1) and dd < st.reach + 10 and
               math.random() < S.chain then
          o.chained = o.chained + 1
          AI.start(o, "attack", dd)
        else
          local tired = S.tired and o.chained >= (S.chains or 1)
          o.chained = 0
          o.cd = (S.wait[1] + math.random(0, S.wait[2] - S.wait[1])) / o.agg + (tired and S.tired or 0)
          if S.back then o.back, o.backsp = S.back, 1 end
        end
      end
      return
    end
    if o.fury then o.fury = o.fury - 1; if o.fury <= 0 then o.fury = nil end end
    if o.cd > 0 then o.cd = o.cd - 1 end
    if o.react_cd > 0 then o.react_cd = o.react_cd - 1 end
    if o.boss and not o.awake then
      if alive and dd < 112 then
        o.awake = true
        FOE.boss = o
        sfx_roar()
      end
      step(o)
      return
    end
    if o.boss and alive then
      local h = o.hp / o.hpmax
      local ph = h > 0.66 and 1 or h > 0.33 and 2 or 3
      if ph > o.ph then
        -- its next phase: it roars (the hound howls), then fights another way
        o.ph, o.style, o.next, o.queue, o.back = ph, AI.BOSS[o.name][ph], nil, nil, 0
        if o.style.fury then o.fury = 1e9 end
        sfx_roar()
        FOE.shake = 16
        o.dir = dir_to(dx, dy)
        if o.name == "hound" and ph == 2 then
          AI.start(o, "howl", dd)
        else
          o.act, o.rage = "rage", 50
          play(o, "hurt")
        end
        return
      end
    end
    -- a boss keeps to its ground
    local hx, hy = o.hx - o.x, o.hy - o.y
    if o.boss and hx * hx + hy * hy > 200 * 200 then
      o.dir = dir_to(hx, hy)
      local hd = sqrt(hx * hx + hy * hy)
      AI.slide(o, hx / hd * st.sp, hy / hd * st.sp)
      if o.anim ~= "walk" then play(o, "walk") end
      step(o)
      return
    end
    if alive and not o.alert and dd < st.sight then
      o.alert = true
      if math.random() < 0.5 then sfx_cry(o) end
    end
    if o.alert and alive and dd > st.sight * 1.8 and not o.boss then o.alert = false end
    if o.alert and alive then
      o.dir = dir_to(dx, dy)
      -- backing off, after its blow or from the hunter's
      if o.back > 0 then
        o.back = o.back - 1
        AI.go(o, -dx, -dy, dd, o.backsp)
        return
      end
      -- the hunter swings at it: some step away, some strike back in his blow
      local pa = P.act
      if (pa == "attack" or pa == "heavy") and dd < st.reach + 26 then
        if S.react and P.f <= 2 and o.react_cd <= 0 then
          o.react_cd = 50
          if math.random() < S.react then
            o.back, o.backsp, o.dodges = 12, 1.8, (o.dodges or 0) + 1
            return
          end
        elseif S.punish and o.cd > 0 and P.f > HUNT[P.anim].hit then
          o.cd, o.counters = 0, (o.counters or 0) + 1
        end
      end
      if o.cd <= 0 then
        local want = o.next
        if not want then
          if o.boss then
            want = AI.choice(o, dd)
            if want == "" then
              want, o.cd, o.closing = nil, 15 + math.random(15), 40  -- a few steps closer first
            elseif want then
              local q = AI.seq(want)
              want, o.queue = q[1], #q > 1 and { table.unpack(q, 2) } or nil
              o.next, o.chase = want, 0
            end
          else
            want = "attack"
          end
        end
        if want then
          if dd <= (AI.RANGE[want] or st.reach + (st.ranged and 0 or 6)) then
            o.next = nil
            AI.start(o, want, dd)
            return
          end
          -- out of its reach: it closes in, quicker (a boss gives up after a while)
          o.chase = (o.chase or 0) + 1
          if o.boss and o.chase > 80 then o.next, o.queue, o.cd = nil, nil, 20 end
          AI.go(o, dx, dy, dd, S.rush or 1)
          return
        end
      end
      -- between its blows: the distance it likes, circling the hunter (a boss
      -- coming closer: within its reach)
      local keep = S.keep or st.reach
      if o.closing and o.closing > 0 then o.closing, keep = o.closing - 1, st.reach end
      if S.flee and dd < S.flee then
        AI.go(o, -dx, -dy, dd, 1)
        return
      elseif dd > keep + 8 then
        AI.go(o, dx, dy, dd, S.stalk or 1)
        return
      elseif dd < keep - 12 and not S.orbit then
        AI.go(o, -dx, -dy, dd, 0.6)                      -- too close: it gives itself room
        return
      elseif S.orbit then
        if math.random() < 0.012 then o.side = -o.side end
        local sp, k = st.sp * S.orbit, (dd - keep) * 0.04
        AI.slide(o, (-dy * o.side * sp + dx * k) / dd, (dx * o.side * sp + dy * k) / dd)
        if o.anim ~= "walk" then play(o, "walk") end
        step(o, S.orbit)
        return
      end
    end
    if o.anim ~= "idle" then play(o, "idle") end
    step(o)
  end

  -- passive (the title): nobody hunts, the ones on screen breathe
  function FOE.update(passive)
    local alive = P.act ~= "dead" and not passive
    if FOE.shake > 0 then FOE.shake = FOE.shake - 1 end
    if FOE.won then FOE.won_t = FOE.won_t + 1; if FOE.won_t > 300 then FOE.won = nil end end
    if FOE.flash then FOE.flash[3] = FOE.flash[3] - 1; if FOE.flash[3] <= 0 then FOE.flash = nil end end
    local i = 1
    while i <= #list do
      local o = list[i]
      local dx, dy = o.x - P.x, o.y - P.y
      local far = dx * dx + dy * dy > 300 * 300
      -- gone with their streets, or long dead
      local cx, cy = fdiv(o.x, CPX), fdiv(o.y, CPX)
      if (far and not chunk(cx, cy)) or (o.act == "dead" and o.corpse > 1200 and far) then
        if FOE.boss == o then FOE.boss = nil end
        table.remove(list, i)
      else
        if o.act or o.alert or o.boss then
          think(o, alive)
        elseif not far then
          -- out of sight it only stands and breathes (half as often)
          local s = o.st.sight
          if dx * dx + dy * dy < s * s then think(o, alive)
          elseif (t + i) % 2 == 0 then step(o, 2) end
        elseif (t + i) % 2 == 0 and o.x > cam_x - 40 and o.x < cam_x + W + 40 and o.y > cam_y - 20 and
               o.y < cam_y + H + 80 then
          step(o, 2)
        end
        o.z = o.act == "dead" and o.y - 6 or o.y
        i = i + 1
      end
    end
    -- creatures on the move do not walk through one another (every other tick)
    if t % 2 == 0 then
      for a = 1, #list do
        local p = list[a]
        if p.alert and p.act ~= "dead" then
          for b = 1, #list do
            local q = list[b]
            if q ~= p and q.act ~= "dead" then
              local dx, dy = q.x - p.x, q.y - p.y
              local rr = (p.st.r + q.st.r) * 0.7
              local d2 = dx * dx + dy * dy
              if d2 < rr * rr and d2 > 0.01 then
                local d = sqrt(d2)
                local push = (rr - d) * 0.5 / d
                move(p, -dx * push, -dy * push)
              end
            end
          end
        end
      end
    end
    -- balls and bombs
    for k = #shots, 1, -1 do
      local s = shots[k]
      if s.kind == "ball" then
        s.x, s.y, s.t = s.x + s.vx, s.y + s.vy, s.t - 1
        local dx, dy = P.x - s.x, P.y - s.y
        if alive and dx * dx + dy * dy < 64 then
          hurt(s.dmg, false)
          s.t = 0
        elseif solid_at(s.x, s.y) then
          for _ = 1, 4 do spawn(s.x, s.y - s.h, (math.random() - 0.5) * 2, -math.random(), 10, 4) end
          s.t = 0
        elseif BRK.touch(s.x, s.y, s.vx, s.vy, 1) then
          s.t = 0
        end
        if s.t <= 0 then table.remove(shots, k) end
      else
        s.t = s.t + 1
        local u = s.t / s.T
        s.x, s.y = s.x0 + (s.tx - s.x0) * u, s.y0 + (s.ty - s.y0) * u
        s.h = s.h0 * (1 - u) + sin(u * PI) * 46
        if math.random() < 0.6 then spawn(s.x, s.y - s.h, 0, -0.3, 12, 1) end
        if s.t >= s.T then
          burns[#burns + 1] = { x = s.x, y = s.y, t = 260, acc = 0 }
          sfx_boom()
          for _ = 1, 20 do
            local an = math.random() * 2 * PI
            spawn(s.x, s.y - 2, cos(an) * 1.4, sin(an) * 0.8 - 0.8, 16 + math.random(16), 1)
          end
          table.remove(shots, k)
        end
      end
    end
    -- fire on the stones: it burns a while
    for k = #burns, 1, -1 do
      local b = burns[k]
      b.t = b.t - 1
      b.acc = b.acc + (b.t > 60 and 1.2 or 0.4)
      while b.acc >= 1 do
        b.acc = b.acc - 1
        spawn(b.x + (math.random() - 0.5) * 26, b.y + (math.random() - 0.5) * 12, (math.random() - 0.5) * 0.3,
              -0.5 - math.random() * 0.8, 14 + math.random(20), 1)
      end
      local ex, ey = (P.x - b.x) / 16, (P.y - b.y) / 9
      if alive and ex * ex + ey * ey < 1 then hurt(1, false) end
      if b.t <= 0 then table.remove(burns, k) end
    end
    -- shock waves along the ground
    for k = #rings, 1, -1 do
      local g = rings[k]
      g.r = g.r + 2.4
      if g.dmg > 0 and not g.hit and alive then
        local dx, dy = P.x - g.x, (P.y - g.y) * 1.6
        local dd = sqrt(dx * dx + dy * dy)
        if abs(dd - g.r) < 7 then g.hit = true; hurt(g.dmg, g.heavy) end
      end
      if g.r >= g.rmax then table.remove(rings, k) end
    end
    -- the Watcher's gaze
    for _, o in ipairs(list) do
      local b = o.beam
      if b then
        b.t = b.t - 1
        if b.t <= 0 or o.act == "dead" then
          o.beam = nil
        elseif alive then
          local lx, ly = b.tx - b.ex, b.ty - b.ey
          local ll = lx * lx + ly * ly
          local px, py = P.x, P.y - 10
          local tt = max(0, ((px - b.ex) * lx + (py - b.ey) * ly) / ll)
          local qx, qy = b.ex + lx * tt - px, b.ey + ly * tt - py
          if qx * qx + qy * qy < 64 then hurt(2, false) end
        end
      end
    end
    if FOE.boss and (FOE.boss.act == "dead" or not alive) then
      if not alive then FOE.boss.awake = false end
      FOE.boss = nil
    end
  end

  -- after the hunter dies: the town fills again, the bosses wait whole
  function FOE.reset()
    FOE.respawns = FOE.respawns + 1
    BRK.reset()
    for k = #list, 1, -1 do
      local o = list[k]
      if o.boss and o.act ~= "dead" then
        o.x, o.y, o.hp, o.awake, o.act, o.alert, o.beam, o.fury = o.hx, o.hy, o.st.hp, false, nil, false, nil, nil
        o.ph, o.style, o.back, o.cd = 1, FOE.style_of(o.name, 1), 0, 30
        o.hold, o.queue, o.next, o.chase = nil, nil, nil, nil
        play(o, "idle")
      else
        table.remove(list, k)
      end
    end
    for _, ch in pairs(chunks) do
      ch.spawned = false
    end
    for k = #shots, 1, -1 do shots[k] = nil end
    for k = #rings, 1, -1 do rings[k] = nil end
    for k = #burns, 1, -1 do burns[k] = nil end
    FOE.boss = nil
  end

  ----------------------------------------------------------- drawing
  function FOE.draw(o)
    local fr, flip = frame(o)
    if flip then
      sspr(fr[1], fr[2], fr[3], fr[4], floor(o.x) - (fr[3] - fr[5]), floor(o.y) - fr[6], true)
    else
      sspr(fr[1], fr[2], fr[3], fr[4], floor(o.x) - fr[5], floor(o.y) - fr[6])
    end
  end
  -- the lights they carry: torches, the lantern's head, the gaze, flashes
  function FOE.lights()
    for _, o in ipairs(list) do
      if o.act ~= "dead" and abs(o.x - P.x) < 200 and abs(o.y - P.y) < 200 then
        if o.st.torch then
          local x, y = point(o, 2)
          glow(x, y, 44 + sin(t * 0.4 + o.x) * 2, 6, 0.5)
        elseif o.st.lantern then
          local x, y = point(o, 2)
          glow(x, y, 26, 3, 0.6)
        end
      end
      if o.beam then glow(o.beam.ex, o.beam.ey, 40, 6, 0.4) end
    end
    for _, b in ipairs(burns) do glow(b.x, b.y - 4, b.t > 60 and 46 or 30, 6, 0.5) end
    for _, s in ipairs(shots) do if s.kind == "bomb" then glow(s.x, s.y - s.h, 22, 5, 0.5) end end
    if FOE.flash then glow(FOE.flash[1], FOE.flash[2], 30 + FOE.flash[3] * 8, 7, 0.4) end
  end
  -- drawn after the light: what shines
  function FOE.fx()
    for _, s in ipairs(shots) do
      if s.kind == "ball" then
        line(s.x, s.y - s.h, s.x - s.vx * 2, s.y - s.h - s.vy * 2, 0xF8E8A0)
      else
        circfill(s.x, s.y - s.h, 2, 0xA06030)
        pset(s.x, s.y - s.h - 2, (t // 2) % 2 == 0 and 0xF8F8D8 or 0xF8C050)
      end
    end
    for _, b in ipairs(burns) do
      local k = b.t > 60 and 1 or b.t / 60
      local fl = sin(t * 0.5 + b.x)
      circfill(b.x, b.y, (8 + fl) * k, 0xA83818)
      circfill(b.x - 3, b.y - 1, (5 + fl * 0.5) * k, 0xE06020)
      circfill(b.x + 2, b.y - 2, 3 * k, 0xF8C050)
    end
    for _, g in ipairs(rings) do
      circ(g.x, g.y, g.r, g.c)
      if g.r > 4 then circ(g.x, g.y, g.r - 3, 0x605850) end
    end
    for _, o in ipairs(list) do
      local b = o.beam
      if b then
        local w = b.t > 60 and 1 or 2
        local lx, ly = b.tx - b.ex, b.ty - b.ey
        local ll = max(1, sqrt(lx * lx + ly * ly))
        local ex, ey = b.ex + lx / ll * 170, b.ey + ly / ll * 170
        line(b.ex, b.ey, ex, ey, 0xB0F0F8)
        if w > 1 then
          line(b.ex + 1, b.ey, ex + 1, ey, 0x58C8D8)
          line(b.ex - 1, b.ey, ex - 1, ey, 0x58C8D8)
        end
        circfill(b.ex, b.ey, 2 + (t // 3) % 2, 0xF8F0C0)
      end
    end
    if FOE.flash then
      local f = FOE.flash
      circfill(f[1], f[2], f[3] > 3 and 4 or 2, 0xF8C050)
      circfill(f[1], f[2], 1, 0xF8F8D8)
    end
    for _, o in ipairs(list) do
      if o.act == "stagger" and (t // 4) % 2 == 0 then FOE.mark(o, 0xF8F8E8) end
      -- a blow held at the top: its weapon glints (the moment to read it)
      if o.hold and o.hold > 0 and (o.hold // 3) % 2 == 0 then
        local x, y = point(o, 1)
        pset(x, y, 0xF8F8E8); pset(x - 2, y, 0xC8C0B0); pset(x + 2, y, 0xC8C0B0)
        pset(x, y - 2, 0xC8C0B0); pset(x, y + 2, 0xC8C0B0)
      end
    end
  end
  -- a small diamond over a creature's head
  function FOE.mark(o, c)
    local fr = frame(o)
    local x, y = floor(o.x), floor(o.y) - fr[6] - 6
    pset(x, y - 2, c); pset(x - 2, y, c); pset(x + 2, y, c); pset(x, y + 2, c)
    pset(x - 1, y - 1, c); pset(x + 1, y - 1, c); pset(x - 1, y + 1, c); pset(x + 1, y + 1, c)
  end

  -- the boss's name and health, at the foot of the screen
  function FOE.hud()
    local o = FOE.boss
    if o and o.awake and o.act ~= "dead" then
      rectfill(0, 224, W, 32, 0x000000)
      local name = o.def.title
      print(name, (W - #name * 8) // 2 // 8 * 8, 224, 0xD8C8A0)
      rectfill(23, 243, 210, 6, 0x180808)
      rectfill(24, 244, floor(208 * max(0, o.hp) / o.st.hp), 4, 0xA01818)
    end
    if FOE.won then
      local k = FOE.won_t
      rectfill(0, 104, W, 48, 0x080604)
      print("PREY SLAUGHTERED", 0, 112, k > 20 and 0xE8C878 or 0x786040, 2)
    end
  end
end

-- back at the last hunter's lamp lit (the start, if none), whole again;
-- the town fills again
local function respawn()
  FOE.reset()
  P.x, P.y = G.spawn and G.spawn[1] or P.home[1], G.spawn and G.spawn[2] or P.home[2]
  P.hp, P.act, P.inv, P.dir, P.rally, P.st, P.lock, P.vic = P.hpmax, nil, 90, 0, 0, P.stmax, nil, nil
  play(xname("idle"))
  cam_x, cam_y = P.x - W / 2, P.y - H * 0.62
end

-- echoes are dear: a little blood costs a good part of an area's prey, a
-- death more, and a path at a lamp (at most four) much more
local DEATH_COST, HEAL_COST, HEAL_HP = 200, 120, 3
local SLOT_COST = { 800, 1200, 1600, 2000 }
-- The paths a hunter takes at the lamps: four at most, any of them again.
-- The first one taken is his own: it gives all it has, and taken again a
-- little less every time (curve: each path in its own way). Any other path
-- is walked with a divided blood (DISCORD): about a third, less the more
-- paths, so a hunter is made by one path, with a turn of another at most.
-- What they do is felt, never shown: no bar grows, no number is told.
-- apply(m, w): w is the weight of the path in the hunter (1: taken once,
-- his own; tests/yharnam/balance.lua measures what it makes of a fight)
local DISCORD = { 1, 0.35, 0.2, 0.15 }
local PATHS = {
  { name = "Feral Affinity", lore = { "blood thick as a beast's;", "blows sink in, and pass" },
    curve = { 1, 0.6, 0.35, 0.25 },
    apply = function(m, w) m.hurt = 1 - 0.19 * w end },
  { name = "Moonlit Breath", lore = { "a breath that outlasts", "the night" },
    curve = { 1, 0.65, 0.45, 0.3 },
    apply = function(m, w) m.st_cost, m.st_regen = 1 / (1 + 0.25 * w), 1 + 0.25 * w end },
  { name = "Quicksilver Rite", lore = { "the bullet knows", "the moment" },
    curve = { 1, 0.6, 0.45, 0.35 },
    apply = function(m, w) m.gun, m.parry, m.stag = 1 + w, 5 * w, 1 + 0.3 * w end },
  { name = "Serrated Oath", lore = { "the open saw", "bites deeper" },
    curve = { 1, 0.7, 0.5, 0.35 },
    apply = function(m, w) m.ext_dmg = 1 + 0.25 * w end },
  { name = "Hunter's Path", lore = { "the folded blade,", "quick as thought" },
    curve = { 1, 0.65, 0.45, 0.3 },
    apply = function(m, w)
      m.fold_rate, m.fold_cost = 1 + 0.2 * w, 1 / (1 + 0.15 * w)
      m.fold_chain = w >= 1                      -- the combo goes on a frame sooner
    end },
}
local ROMAN = { "I", "II", "III", "IV" }
local menu = { i = 1, page = nil }

-- the weight of each path in the hunter: every taking as the curve of its
-- path (how many times taken) and the discord (how many paths before it)
local function path_weights(slots)
  local w, times, rank, ranks = {}, {}, {}, 0
  for _, i in ipairs(slots) do
    if not rank[i] then ranks = ranks + 1; rank[i] = ranks end
    times[i] = (times[i] or 0) + 1
    w[i] = (w[i] or 0) + PATHS[i].curve[times[i]] * DISCORD[rank[i]]
  end
  return w
end

-- the hunter as his paths made him
local function apply_paths()
  local m = { hurt = 1, st_cost = 1, st_regen = 1, gun = 1, parry = 0, stag = 1, ext_dmg = 1, fold_rate = 1,
              fold_cost = 1, fold_chain = false }
  for i, w in pairs(path_weights(G.slots)) do PATHS[i].apply(m, w) end
  P.mods = m
end

-- a new hunt: no echoes, no lamps lit, the first area only, from the start
local function new_hunt()
  G.open, G.echoes, G.lit, G.spawn, G.lost, G.popups, G.slots = 1, 0, {}, nil, false, {}, {}
  apply_paths()
  for k in pairs(FOE.slain) do FOE.slain[k] = nil end
  respawn()
  P.inv = 0
end

-- the hunter's lamp in reach, if any
local function shrine_near()
  local pcx, pcy = fdiv(P.x, CPX), fdiv(P.y, CPX)
  for cy = pcy - 1, pcy + 1 do
    for cx = pcx - 1, pcx + 1 do
      local ch = chunk(cx, cy)
      local sh = ch and ch.ready and ch.shrine
      if sh and abs(sh.x - P.x) < 22 and abs(sh.y + 12 - P.y) < 20 then return sh end
    end
  end
end

local function update_play()
  if btnp(8) and P.act ~= "dead" then
    state, menu.i, menu.page = "pause", 1, nil
    return
  end
  local dx, dy = 0, 0
  if btn(0) then dx = dx - 1 end
  if btn(1) then dx = dx + 1 end
  if btn(2) then dy = dy - 1 end
  if btn(3) then dy = dy + 1 end
  if P.inv > 0 then P.inv = P.inv - 1 end
  if P.rally_t > 0 then P.rally_t = P.rally_t - 1; if P.rally_t == 0 then P.rally = 0 end end
  -- the shoulder buttons (L1 locks on, R1 the heavy blow), B tapped or held
  local pd = pad()
  local l1, r1 = pd & 1024 ~= 0, pd & 2048 ~= 0
  local l1p, r1p = l1 and not P.l1, r1 and not P.r1
  P.l1, P.r1 = l1, r1
  if btn(5) then P.bt, P.brel = P.bt + 1, 0 else P.brel, P.bt = P.bt, 0 end
  if P.st_wait > 0 then P.st_wait = P.st_wait - 1
  elseif P.st < P.stmax then P.st = min(P.stmax, P.st + 1.4 * P.mods.st_regen) end
  if l1p then
    P.lock = not P.lock and FOE.nearest(150) or nil
    note(2, P.lock and 1600 or 800, 60, TRIANGLE, 40)
  end
  local L = P.lock
  if L and (L.act == "dead" or abs(L.x - P.x) + abs(L.y - P.y) > 260) then P.lock = nil end
  if flash > 0 then flash = flash - 1 end
  if tracer then tracer[5] = tracer[5] - 1; if tracer[5] <= 0 then tracer = nil end end
  local pcx, pcy = fdiv(P.x, CPX), fdiv(P.y, CPX)
  -- lamps in reach
  near_lamp = nil
  if not P.act then
    for cy = pcy - 1, pcy + 1 do
      for cx = pcx - 1, pcx + 1 do
        local ch = chunk(cx, cy)
        if ch and ch.ready then
          for _, l in ipairs(ch.lamps) do
            if abs(l.x - P.x) < 22 and abs(l.y - P.y) < 18 then
              if not lamp_state[l.key] then near_lamp = l end
            end
          end
        end
      end
    end
  end

  local act = P.act
  local shrine = not act and shrine_near()
  P.shrine = shrine
  if not act then
    P.moving = dx ~= 0 or dy ~= 0
    if btnp(4) and shrine then
      if not G.lit[shrine.key] then
        -- lit: it is where the hunter comes back to, whole again
        G.lit[shrine.key] = true
        sfx_light()
        for k = 1, 30 do
          local a = math.random() * 2 * PI
          spawn(shrine.x, shrine.y - 40, cos(a) * 0.9, sin(a) * 0.9 - 0.6, 30 + math.random(24), 4)
        end
        banner, banner_t = "LAMP LIT", 150
      end
      G.spawn = { shrine.x, shrine.y + 16 }
      P.hp, P.rally, P.st = P.hpmax, 0, P.stmax
      state, menu.i = "lamp", 1
      P.lock = nil
    elseif btnp(9) then
      -- Select: echoes for blood, a little health back
      if G.echoes >= HEAL_COST and P.hp < P.hpmax then
        G.echoes = G.echoes - HEAL_COST
        P.act, P.ht = "heal", 0
        play(xname("idle"))
        note(1, 300, 300, TRIANGLE, 60); note(2, 450, 300, TRIANGLE, 40)
      else
        note(1, 90, 120, SQUARE, 40)
      end
    elseif btnp(4) and near_lamp then
      lamp_state[near_lamp.key] = true
      lamps_lit = lamps_lit + 1
      sfx_light()
      for k = 1, 24 do
        local a = math.random() * 2 * PI
        spawn(near_lamp.x, near_lamp.y - 66, cos(a) * 0.8, sin(a) * 0.8 - 0.6, 30 + math.random(20), 4)
      end
    elseif btnp(4) and FOE.visceral_target() then
      visceral(FOE.visceral_target())
    elseif btnp(4) and P.st > 0 then
      attack(1, dx, dy)
    elseif r1p and P.st > 0 then
      heavy(dx, dy)
    elseif btnp(6) then
      if P.moving then P.dir = DIRS[dy][dx] end
      if P.moving then P.act = "shoot"; play(xname("shoot")) else shoot() end
    elseif btnp(7) then
      P.act = P.ext and "close" or "open"
      play("open", P.ext)
    elseif P.brel > 0 and P.brel < 10 and P.st > 0 then
      dodge(dx, dy)
    elseif P.moving then
      local run = P.bt >= 10 and P.st > 0 and not P.lock
      if run then P.st, P.st_wait = P.st - 0.45 * P.mods.st_cost, 30 end
      P.dir = P.lock and FOE.dir_to(P.lock.x - P.x, P.lock.y - P.y) or DIRS[dy][dx]
      local sp = run and 1.55 or (P.lock and 0.8 or 0.92)
      if dx ~= 0 and dy ~= 0 then sp = sp * 0.7071 end
      walk_by(dx * sp, dy * sp)
      if P.anim ~= xname("walk") then play(xname("walk")) end
      step_anim(run and 1.5 or 1)
      if P.newf and (P.f == 3 or P.f == 7) then sfx_step() end
    else
      if P.lock then P.dir = FOE.dir_to(P.lock.x - P.x, P.lock.y - P.y) end
      if P.anim ~= xname("idle") then play(xname("idle")) end
      step_anim()
    end
  elseif act == "attack" then
    local a = HUNT[P.anim]
    local done = step_anim(BLADE.rate())
    if P.f <= a.hit then forward(P.ext and 0.45 or 0.35) end
    if P.newf and P.f == a.hit then
      sfx_swing(P.ext)
      local b = BLADE.form()
      rally(FOE.strike(BLADE.dmg(b.light[P.combo]), b.reach, P.combo == 3 and 0.5 or 0.1))
    end
    -- the tip of the blade leaves a trail through the blow
    if P.f >= a.hit - 2 and P.f <= a.hit + 1 then
      local fr = a.d[P.dir + 1][P.f]
      P.trail[#P.trail + 1] = { P.x + fr[7], P.y + fr[8], 10 }
    end
    -- after the blow: A goes on, Y transforms the blade in a blow, R1 strikes heavy
    if btnp(4) and P.f >= a.hit - 1 and P.combo < 3 then P.queued = "a" end
    if btnp(7) and P.f >= a.hit - 1 then P.queued = "y" end
    if r1p and P.f >= a.hit - 1 then P.queued = "r" end
    if P.queued and P.f > a.hit + ((not P.ext and P.mods.fold_chain) and 0 or 1) and P.st > 0 then
      local q = P.queued
      if q == "y" then trick() elseif q == "r" then heavy(dx, dy) else attack(P.combo + 1, dx, dy) end
    elseif done then
      P.act, P.combo = nil, 0
    end
  elseif act == "heavy" then
    local a = HUNT[P.anim]
    if P.f == a.charge and r1 and P.charge < 45 then
      -- R1 held at the top of the wind-up: charging
      P.charge = P.charge + 1
      P.st_wait = 30
      if P.charge == 20 then P.charged = true; note(1, 220, 300, SAW, 60); note(2, 880, 300, TRIANGLE, 40) end
    else
      local done = step_anim(BLADE.rate())
      if P.f <= a.hit then forward(P.ext and 0.4 or 0.3) end
      if P.newf and P.f == a.hit then
        sfx_swing(true)
        local b = BLADE.form()
        rally(FOE.strike(BLADE.dmg(b.heavy + (P.charged and b.charged or 0)), b.reach + 2, 0.2, P.charged))
        if P.charged then FOE.shake = 6 end
      end
      if P.f >= a.hit - 2 and P.f <= a.hit + 1 then
        local fr = a.d[P.dir + 1][P.f]
        P.trail[#P.trail + 1] = { P.x + fr[7], P.y + fr[8], 12 }
      end
      if done then P.act, P.combo, P.charged = nil, 0, false end
    end
  elseif act == "trick" then
    local a = HUNT[P.anim]
    local done = step_anim(BLADE.rate())
    if P.f <= a.hit then forward(0.35) end
    if P.newf and P.f == a.hit then
      sfx_swing(true)
      rally(FOE.strike(BLADE.dmg(BLADE.form().trick), 32, 0.0))
    end
    if P.newf and P.f == a.lock then P.ext = not P.ext; sfx_clank() end
    if P.f >= a.hit - 2 and P.f <= a.hit + 1 then
      local fr = a.d[P.dir + 1][P.f]
      P.trail[#P.trail + 1] = { P.x + fr[7], P.y + fr[8], 10 }
    end
    if btnp(4) and P.f >= a.hit - 1 then P.queued = "a" end
    if P.queued and P.f > a.lock and P.st > 0 then
      attack(min(P.combo + 1, 3), dx, dy)               -- the combo goes on, in the other form
    elseif done then
      P.act, P.combo = nil, 0
    end
  elseif act == "qstep" or act == "roll" then
    local done = step_anim()
    local f = P.f
    local sp
    if act == "roll" then sp = (f >= 2 and f <= 6) and 2.2 or 0
    else sp = (f >= 2 and f <= 4) and 3.0 or f == 5 and 1.0 or 0 end
    if sp > 0 then walk_by(P.dv[1] * sp, P.dv[2] * sp) end
    if done then P.act = nil end
  elseif act == "heal" then
    step_anim()
    P.ht = P.ht + 1
    if P.ht % 3 == 0 then spawn(P.x + math.random(-6, 6), P.y - 4, 0, -0.6, 24, 5) end
    if P.ht == 20 then P.hp = min(P.hpmax, P.hp + HEAL_HP) end
    if P.ht >= 40 then P.act = nil end
  elseif act == "visceral" then
    local a = HUNT[P.anim]
    local done = step_anim()
    if P.newf and P.f == a.hit and P.vic then
      FOE.visceral(P.vic, BLADE.form().visceral)
      rally(P.rally)
    end
    if done then P.act, P.vic, P.inv = nil, nil, 0 end
  elseif act == "shoot" then
    local done = step_anim()
    if P.newf and P.f == HUNT[P.anim].fire then fire() end
    if done then P.act = nil end
  elseif act == "open" or act == "close" then
    local done = step_anim()
    if P.newf and P.f == HUNT.open.lock then sfx_clank() end
    if done then P.act, P.ext = nil, act == "open" end
  elseif act == "backstep" then
    local done = step_anim()
    if P.f >= 2 and P.f <= 5 then forward(P.f >= 3 and P.f <= 4 and -2.4 or -1.2) end
    if done then P.act = nil end
  elseif act == "hurt" then
    local done = step_anim()
    if P.f <= 2 then forward(-0.6) end
    if done then P.act = nil end
  elseif act == "down" then
    local done = step_anim()
    if P.f <= 5 then forward(-1.4) end
    if P.newf and P.f == 5 then sfx_fall() end
    if done then P.act, P.lie = "lying", 50 end
  elseif act == "lying" then
    P.lie = P.lie - 1
    if P.lie <= 0 or (P.lie < 30 and (btnp(4) or btnp(5))) then
      P.act = "getup"
      play(xname("getup"))
    end
  elseif act == "getup" then
    if step_anim() then P.act, P.inv = nil, 40 end
  elseif act == "dead" then
    if not step_anim() then
      if P.newf and P.f == 8 then sfx_fall() end
    else
      died_t = died_t + 1
      if died_t > 150 then
        -- a death costs echoes; with too few, the hunt is lost
        if G.echoes >= DEATH_COST then
          G.echoes = G.echoes - DEATH_COST
          respawn()
          G.popups[#G.popups + 1] = { x = P.x, y = P.y - 40, t = 90, s = "-" .. DEATH_COST .. " echoes" }
        else
          G.lost, state, t = true, "lost", 0
        end
      end
    end
  end
  for i = #P.trail, 1, -1 do
    local tr = P.trail[i]
    tr[3] = tr[3] - 1
    if tr[3] <= 0 then table.remove(P.trail, i) end
  end

  -- fire burns: braziers and pyres
  if P.act ~= "dead" then
    for cy = pcy - 1, pcy + 1 do
      for cx = pcx - 1, pcx + 1 do
        local ch = chunk(cx, cy)
        if ch and ch.ready then
          for _, f in ipairs(ch.fires) do
            local bx, by = f.x, f.y + (f.big and 10 or 25)
            local r = f.big and 26 or 16
            local ex, ey = (P.x - bx) / r, (P.y - by) / (r * 0.6)
            if ex * ex + ey * ey < 1 then hurt(f.big and 3 or 1, f.big and math.random() < 0.5) end
          end
        end
      end
    end
  end

  -- the camera follows, a little ahead of the hunter
  local tx, ty = P.x - W / 2, P.y - H * 0.62
  cam_x = cam_x + (tx - cam_x) * 0.12
  cam_y = cam_y + (ty - cam_y) * 0.12
  if banner_t > 0 then banner_t = banner_t - 1 end
  for i = #G.popups, 1, -1 do
    local pp = G.popups[i]
    pp.t, pp.y = pp.t - 1, pp.y - 0.4
    if pp.t <= 0 then table.remove(G.popups, i) end
  end
  FOE.update()
end

-- for the tests on the PC (tests/yharnam/sim.lua)
YHARNAM = { road_at = road_at, district = district, chunk = chunk, ensure = ensure, player = P,
            blocked = blocked, lamps = lamp_state, kinds = { road = K_ROAD, walk = K_WALK, house = K_HOUSE },
            camera = function() return cam_x, cam_y end, CS = CS, TS = TS, SPR = SPR, FACADE = FACADE,
            HUNT = HUNT, FOES = FOES, FOE = FOE, hurt = hurt, flash = function() return flash end, dirs = DIRS,
            G = G, AREA = AREA, boss_chunk = boss_chunk, lamp_chunk = lamp_chunk, PATHS = PATHS, menu = menu,
            apply_paths = apply_paths, path_weights = path_weights, BLADE = BLADE, parts = parts, BRK = BRK,
            state = function() return state end,
            teleport = function(x, y)
              P.x, P.y = x, y
              cam_x, cam_y = x - W / 2, y - H * 0.62
              state = "play"
            end }

-- the animation viewer of the title screen: every animation of the hunter
-- and of every creature, every direction
local GALLERY = {}
for _, n in ipairs({ "idle", "walk", "shoot", "slash1", "slash2", "slash3", "backstep", "hurt1", "hurt2", "hurt3",
                     "down", "getup", "death", "open", "idle_x", "walk_x", "shoot_x", "xslash1", "xslash2",
                     "xslash3", "backstep_x", "hurt1_x", "hurt2_x", "hurt3_x", "down_x", "getup_x",
                     "death_x" }) do
  GALLERY[#GALLERY + 1] = { anim = n }
end
for _, f in ipairs(FOES) do
  -- shown twice as big, if it fits
  local tall = 0
  for _, a in pairs(f.a) do
    for _, d in ipairs(a.d) do
      for _, fr in ipairs(d) do tall = max(tall, fr[6]) end
    end
  end
  f.zoom = tall <= 66 and 2 or 1
  for _, n in ipairs(f.order) do GALLERY[#GALLERY + 1] = { def = f, anim = n } end
end
local gal = { i = 1, wait = 0, o = { def = FOES[1], anim = "idle", f = 1, ft = 0, dir = 0, x = 0, y = 0 } }
local function gal_start()
  local g = GALLERY[gal.i]
  gal.wait = 0
  if g.def then
    gal.o.def = g.def
    FOE.play(gal.o, g.anim)
  else
    play(g.anim)
  end
end

function _init()
  -- the fade tables: every colour of the sheet at the 8 light levels.
  -- Level 1 is the night (dim, blue: the twilight of a dead town), 7 the
  -- warm light under a lamp; glass of lit windows, flames and embers keep
  -- their colour at every level: they make their own light.
  local rows = {}
  for _, c in ipairs(PALETTE) do
    local row = { c }
    local r, g, b = c >> 16, (c >> 8) & 255, c & 255
    local lum = 0.30 * r + 0.59 * g + 0.11 * b
    for k = 0, LEVELS - 1 do
      local o = c
      if not GLOWING[c] then
        local nr, ng, nb = r * 0.13 + lum * 0.03, g * 0.14 + lum * 0.05, b * 0.20 + lum * 0.12
        if k == 0 then nr, ng, nb = nr * 0.45, ng * 0.45, nb * 0.55 end
        local wr, wg, wb = min(255, r * 1.10 + 8), min(255, g * 0.97 + 2), b * 0.76
        local f = k <= 1 and 0 or ((k - 1) / (LEVELS - 2)) ^ 1.15
        local fr, fg, fb = nr + (wr - nr) * f, ng + (wg - ng) * f, nb + (wb - nb) * f
        o = ((floor(fr) // 8 * 8) << 16) | ((floor(fg) // 8 * 8) << 8) | (floor(fb) // 8 * 8)
      end
      row[k + 2] = o
    end
    rows[#rows + 1] = row
  end
  fades(rows)
  place_player()
  P.home = { P.x, P.y }
  cam_x, cam_y = P.x - W / 2, P.y - H * 0.62
end

function _update()
  t = t + 1
  if state == "title" then
    -- after a moment the camera drifts over the town: the hunter starts
    -- wherever it is when A is pressed
    if t > 150 then
      cam_x, cam_y = cam_x + 0.9, cam_y + 0.45
    end
    if btnp(4) or btnp(5) then
      state = "play"
      new_hunt()
    elseif btnp(6) then
      state, gal.i = "gallery", 1
      P.dir = 0
      gal_start()
    end
    if P.anim ~= "idle" then play("idle") end
    step_anim()
    FOE.update(true)
  elseif state == "lamp" then
    -- at a hunter's lamp: rest, take a path with echoes, or leave
    local n = #PATHS + 2
    if btnp(2) then menu.i = (menu.i - 2) % n + 1 end
    if btnp(3) then menu.i = menu.i % n + 1 end
    if btnp(5) or (btnp(4) and menu.i == n) then
      state = "play"
    elseif btnp(4) and menu.i == 1 then
      -- rest: whole again, and the town fills again
      FOE.reset()
      P.hp, P.st, P.rally = P.hpmax, P.stmax, 0
      state = "play"
      note(1, 392, 500, TRIANGLE, 60); note(2, 523, 500, TRIANGLE, 40)
    elseif btnp(4) then
      local k = #G.slots + 1
      if k <= #SLOT_COST and G.echoes >= SLOT_COST[k] then
        G.echoes = G.echoes - SLOT_COST[k]
        G.slots[k] = menu.i - 1
        apply_paths()
        note(0, 98, 900, SAW, 70); note(1, 392, 700, TRIANGLE, 70); note(2, 587, 900, TRIANGLE, 50)
        local sh = P.shrine
        if sh then
          for _ = 1, 40 do
            local an = math.random() * 2 * PI
            spawn(sh.x, sh.y - 30, cos(an) * 1.2, sin(an) * 1.2 - 0.4, 30 + math.random(30), 5)
          end
        end
      else
        note(1, 90, 120, SQUARE, 40)
      end
    end
  elseif state == "pause" then
    -- the pause: resume, the controls, or give the hunt up
    if menu.page then
      if btnp(4) or btnp(5) or btnp(8) then menu.page = nil end
    else
      if btnp(2) then menu.i = (menu.i - 2) % 3 + 1 end
      if btnp(3) then menu.i = menu.i % 3 + 1 end
      if btnp(5) or btnp(8) or (btnp(4) and menu.i == 1) then
        state = "play"
      elseif btnp(4) and menu.i == 2 then
        menu.page = "controls"
      elseif btnp(4) and menu.i == 3 then
        state, t = "title", 0
        new_hunt()
      end
    end
    return
  elseif state == "lost" then
    if t > 90 and (btnp(4) or btnp(5)) then
      state, t = "title", 0
      new_hunt()
    end
  elseif state == "gallery" then
    if btnp(0) then P.dir = (P.dir + 1) % 8 end
    if btnp(1) then P.dir = (P.dir + 7) % 8 end
    if btnp(2) or btnp(3) then
      gal.i = (gal.i + (btnp(3) and 0 or -2)) % #GALLERY + 1
      gal_start()
    elseif btnp(7) then
      -- Y: the next creature, at its first animation
      local cur = GALLERY[gal.i].def
      repeat gal.i = gal.i % #GALLERY + 1 until GALLERY[gal.i].def ~= cur
      gal_start()
    end
    local g = GALLERY[gal.i]
    gal.o.dir = P.dir
    if btnp(5) or btnp(6) then
      state, t = "title", 0
      play("idle")
    elseif gal.wait > 0 then
      gal.wait = gal.wait - 1
      if gal.wait == 0 then gal_start() end
    elseif (g.def and FOE.step(gal.o)) or (not g.def and step_anim()) then
      gal.wait = 40
    end
    return
  else
    update_play()
  end
  stream()
  if t % 15 == 0 then FOE.spawn_around() end
  update_parts()
end

----------------------------------------------------------------- drawing

local function draw_map()
  local tx0, ty0 = fdiv(cam_x, TS), fdiv(cam_y, TS)
  local tx1, ty1 = fdiv(cam_x + W - 1, TS), fdiv(cam_y + H - 1, TS)
  local ty = ty0
  while ty <= ty1 do
    local ry = ty % RT
    local nty = min(ty1 - ty + 1, RT - ry)
    local tx = tx0
    while tx <= tx1 do
      local rx = tx % RT
      local ntx = min(tx1 - tx + 1, RT - rx)
      map(rx * 2, ry * 2, tx * TS, ty * TS, ntx * 2, nty * 2)
      map(128 + rx * 2, ry * 2, tx * TS, ty * TS, ntx * 2, nty * 2)
      tx = tx + ntx
    end
    ty = ty + nty
  end
end

local vis = {}
local function by_depth(a, b) return a.z < b.z end     -- everything drawn in depth order has a z
local function visible_chunks(margin)
  local out = {}
  for cy = fdiv(cam_y - margin, CPX), fdiv(cam_y + H + margin, CPX) do
    for cx = fdiv(cam_x - margin, CPX), fdiv(cam_x + W + margin, CPX) do
      local ch = chunk(cx, cy)
      if ch and ch.ready then out[#out + 1] = ch end
    end
  end
  return out
end

-- the edge of the hunt (the areas open so far): a drifting wall of mist
local MIST = { 0xC8D0D8, 0x8890A0, 0x585C68 }
local function draw_edge()
  local x1, y1 = G.open * AREA * CPX, AREA * CPX
  local ya, yb = max(0, cam_y - 4), min(y1, cam_y + H + 4)
  local xa, xb = max(0, cam_x - 4), min(x1, cam_x + W + 4)
  for _, e in ipairs({ { 0, 1 }, { x1, -1 } }) do
    local x = e[1]
    if x > cam_x - 12 and x < cam_x + W + 12 then
      for k = 0, 2 do
        local xx, c = x + e[2] * k * 3, MIST[k + 1]
        local y = ya - (t * (k + 1) // 2) % 20
        while y < yb do
          line(xx, max(ya, y), xx, min(yb, y + 6 + (k * 5 + y // 20) % 8), c)
          y = y + 20
        end
      end
    end
  end
  for _, e in ipairs({ { 0, 1 }, { y1, -1 } }) do
    local y = e[1]
    if y > cam_y - 12 and y < cam_y + H + 12 then
      for k = 0, 2 do
        local yy, c = y + e[2] * k * 3, MIST[k + 1]
        local x = xa - (t * (k + 1) // 2) % 20
        while x < xb do
          line(max(xa, x), yy, min(xb, x + 6 + (k * 5 + x // 20) % 8), yy, c)
          x = x + 20
        end
      end
    end
  end
end

local function draw_scene()
  local sx, sy = 0, 0
  if FOE.shake > 0 then sx, sy = math.random(-2, 2), math.random(-1, 1) end
  camera(cam_x + sx, cam_y + sy)
  draw_map()
  -- objects and the hunter, back to front
  local n = 0
  local x0, y0, x1, y1 = cam_x - 64, cam_y - 16, cam_x + W + 64, cam_y + H + 140
  local near = visible_chunks(140)
  for _, ch in ipairs(near) do
    for _, o in ipairs(ch.objs) do
      if o.bld then
        if o.x < cam_x + W and o.x + o.w * TS > cam_x and o.top < cam_y + H and o.y > cam_y then
          n = n + 1; vis[n] = o
        end
      elseif o.x > x0 and o.x < x1 and o.y > y0 and o.y < y1 then
        n = n + 1; vis[n] = o
      end
    end
  end
  if state ~= "title" or t <= 150 then
    n = n + 1
    vis[n] = P
    P.z = P.y
  end
  for _, o in ipairs(FOE.list) do
    if o.x > x0 and o.x < x1 and o.y > y0 and o.y < y1 then n = n + 1; vis[n] = o end
  end
  for i = n + 1, #vis do vis[i] = nil end
  table.sort(vis, by_depth)
  for i = 1, n do
    local o = vis[i]
    if o.bld then
      local c = o.bld
      local i0, i1 = max(0, fdiv(cam_x - o.x, TS)), min(o.w - 1, fdiv(cam_x + W - 1 - o.x, TS))
      local j0, j1 = max(0, fdiv(cam_y - o.top, TS)), min(o.h - 1, fdiv(cam_y + H - 1 - o.top, TS))
      for j = j0, j1 do
        local y = o.top + j * TS
        for i = i0, i1 do spr(c[j * o.w + i + 1], o.x + i * TS, y, 2, 2) end
      end
    elseif o.def then
      FOE.draw(o)
    elseif o == P then
      -- after a blow he blinks while he cannot be hurt
      if not (P.act == nil and P.inv > 0 and P.inv < 50 and (P.inv // 3) % 2 == 1) then
        local fr = HUNT[P.anim].d[P.dir + 1][P.f]
        sspr(fr[1], fr[2], fr[3], fr[4], floor(P.x) - fr[5], floor(P.y) - fr[6])
      end
    else
      local s = o.s
      if o.lamp and not lamp_state[o.lamp] then s = SPR.lamp_off end
      if o.shrine then s = G.lit[o.shrine] and SPR.shrine_lit or SPR.shrine end
      sspr(s[1], s[2], s[3], s[4], floor(o.x) - s[5], floor(o.y) - s[6])
    end
  end
  -- smoke: drawn before the lights, so only fires and lamps show it
  for _, p in ipairs(parts) do
    if p.kind == 3 then
      local a = p.t / p.life
      circfill(p.x, p.y, 1 + a * 4, a < 0.5 and 0x585058 or 0x403840)
    elseif p.kind == 5 then
      pset(p.x, p.y, p.t < 8 and 0xB82028 or 0x681018)
    elseif p.kind == 8 then
      line(p.x, p.y, p.x + (p.vy == 0 and 1 or (p.t // 3) % 2), p.y + (p.vy == 0 and 0 or 1), p.c)
    end
  end
  -- the lights
  dark_begin(AMBIENT)
  local fire_near
  for _, ch in ipairs(near) do
    for _, l in ipairs(ch.lights) do
      local rr = l.r
      if l.fl > 0 then
        rr = rr * (1 - l.fl * 0.08 + l.fl * 0.05 * sin(t * 0.31 + l.seed) + l.fl * 0.04 * sin(t * 0.73 + l.seed * 3))
      end
      if l.x + rr > cam_x and l.x - rr < cam_x + W and l.y + rr > cam_y and l.y - rr < cam_y + H then
        glow(l.x, l.y, rr, l.lv, l.d)
      end
    end
    for _, l in ipairs(ch.lamps) do
      if lamp_state[l.key] then
        local rr = 74 + sin(t * 0.05 + l.x) * 1.0
        if l.x + rr > cam_x and l.x - rr < cam_x + W and l.y + rr > cam_y and l.y - rr < cam_y + H then
          glow(l.x, l.y - 6, rr, 7, 0.3)        -- concentric discs, as in Dank Tomb
        end
      end
    end
    for _, f in ipairs(ch.fires) do
      local dd = abs(f.x - P.x) + abs(f.y - P.y)
      if not fire_near or dd < fire_near then fire_near = dd end
    end
    -- a hunter's lamp: lit, a soft breathing aura (not a strong light: the
    -- user's wish, a cold fire, a mystic essence); dark, a faint glimmer
    local sh = ch.shrine
    if sh then
      if G.lit[sh.key] then
        glow(sh.x, sh.y - 30, 46 + sin(t * 0.04) * 4, 5, 0.7)
        glow(sh.x, sh.y - 33, 16, 6, 0.4)
      else
        glow(sh.x, sh.y - 30, 18, 2, 0.7)
      end
    end
  end
  glow(P.x, P.y - 14, 42, 4, 0.7)               -- what the hunter's eyes make out
  FOE.lights()
  if flash > 0 then
    local fr = HUNT[P.anim].d[P.dir + 1][P.f]
    glow(P.x + fr[9], P.y + fr[10], 30 + flash * 9, 7, 0.4)
  end
  dark_end()
  -- the trail of the blade, the flash and the shot
  local tr = P.trail
  for i = 2, #tr do
    local a, b = tr[i - 1], tr[i]
    local c = b[3] > 7 and 0xF0F0E8 or b[3] > 4 and 0xB0B0C0 or 0x686878
    line(a[1], a[2], b[1], b[2], c)
    if b[3] > 5 then line(a[1], a[2] + 1, b[1], b[2] + 1, 0x9090A0) end
  end
  if flash > 0 then
    local fr = HUNT[P.anim].d[P.dir + 1][P.f]
    local mx, my = P.x + fr[9], P.y + fr[10]
    local v = DIRV[P.dir + 1]
    circfill(mx, my, flash > 3 and 3 or 2, 0xF8C050)
    circfill(mx, my, 1, 0xF8F8D8)
    if flash > 2 then
      line(mx, my, mx + v[1] * (6 + flash), my + v[2] * (6 + flash), 0xF8E890)
      line(mx - v[2] * 3, my + v[1] * 3, mx + v[2] * 3, my - v[1] * 3, 0xF89030)
    end
  end
  if tracer then
    line(tracer[1], tracer[2], tracer[3], tracer[4], tracer[5] > 3 and 0xF8E8A0 or 0x907050)
  end
  FOE.fx()
  draw_edge()
  if P.lock and state == "play" then FOE.mark(P.lock, FOE.visceral_target() and 0xF8F8E8 or 0xE04030) end
  -- flames and embers make their own light: drawn after it. Every fire is
  -- a loop of frames (art/fire.py: a bed of embers and tongues of flame,
  -- full at the base, the user's wish), each fire at its own moment of the
  -- loop; then the sparks
  for _, ch in ipairs(near) do
    for _, f in ipairs(ch.fires) do
      if f.x > cam_x - 40 and f.x < cam_x + W + 40 and f.y > cam_y - 64 and f.y < cam_y + H + 32 then
        local an = f.big and FIRE_ANIM.big or FIRE_ANIM.small
        local fr = an[(t // 3 + floor(f.x) * 3) % #an + 1]
        sspr(fr[1], fr[2], fr[3], fr[4], floor(f.x) - fr[5], floor(f.y) + (f.big and 9 or 3) - fr[6])
      end
    end
  end
  for _, p in ipairs(parts) do
    local k = p.kind
    if k == 1 then
      local a = p.t / p.life
      local c = FLAME[min(#FLAME, 2 + floor(a * (#FLAME - 1)))]
      if a < 0.3 then rectfill(p.x, p.y, 2, 2, c) else pset(p.x, p.y, c) end
    elseif k == 2 then
      if (p.t // 3 + p.life) % 4 ~= 0 then pset(p.x, p.y, p.t < p.life * 0.6 and 0xF8B040 or 0xC05020) end
    elseif k == 4 then
      pset(p.x, p.y, 0xF8E8A0)
    elseif k >= 6 then
      local a = p.t / p.life
      local tw = (p.t // 5 + p.life) % 5
      if tw ~= 0 then
        local c = k == 7 and 0x506878 or a > 0.75 and 0x587898 or tw == 1 and 0xF0F8F8 or
                  tw == 3 and 0xB8A8E8 or 0x98D0E8
        pset(p.x, p.y, c)
        if k == 6 and a < 0.6 and (p.t + p.life) % 37 < 3 then        -- now and then a glint
          pset(p.x - 1, p.y, 0x98D0E8); pset(p.x + 1, p.y, 0x98D0E8)
          pset(p.x, p.y - 1, 0x98D0E8); pset(p.x, p.y + 1, 0x98D0E8)
        end
      end
    end
  end
  for _, ch in ipairs(near) do
    local sh = ch.shrine
    if sh and G.lit[sh.key] and abs(sh.x - cam_x - W / 2) < W and abs(sh.y - cam_y - H / 2) < H then
      for k = 0, 9 do
        if (k + t // 6) % 4 ~= 0 then
          local a = t * 0.025 + k * 0.6283
          pset(sh.x + cos(a) * 11, sh.y - 33 + sin(a) * 6, k % 3 == 0 and 0xE8F8F8 or 0x88B8D8)
        end
      end
    end
  end
  camera()
  return fire_near
end

local function emit()
  for _, ch in ipairs(visible_chunks(48)) do
    for _, f in ipairs(ch.fires) do
      f.acc = (f.x > cam_x - 40 and f.x < cam_x + W + 40 and f.y > cam_y - 40 and f.y < cam_y + H + 60) and
              (f.acc or 0) + f.rate or 0                -- only fires seen burn sparks
      while f.acc >= 1 do
        f.acc = f.acc - 1
        local x = f.x + (math.random() - 0.5) * 1.4 * f.w
        local y = f.y - (f.big and 14 or 6) - math.random() * (f.big and 18 or 6)
        spawn(x, y, (math.random() - 0.5) * 0.3, -0.5 - math.random() * (f.big and 1.1 or 0.7),
              14 + math.random(f.big and 30 or 16), 1)
        if math.random() < (f.big and 0.12 or 0.05) then
          spawn(x, y - 6, (math.random() - 0.5) * 0.6, -0.6 - math.random() * 0.8, 50 + math.random(60), 2)
        end
        if f.big and math.random() < 0.08 then
          spawn(f.x + (math.random() - 0.5) * 10, f.y - 40, 0.1, -0.35, 140, 3)
        end
      end
    end
    -- motes of a cold light round a hunter's lamp: many when lit, a few when not
    local sh = ch.shrine
    if sh and math.random() < (G.lit[sh.key] and 0.3 or 0.05) then
      local a, r = math.random() * 2 * PI, 5 + math.random() * 12
      spawn(sh.x + cos(a) * r, sh.y - 33 + sin(a) * r * 0.6, -sin(a) * 0.12, -0.08 - math.random() * 0.12,
            70 + math.random(80), G.lit[sh.key] and 6 or 7)
    end
    for _, s in ipairs(ch.smokes) do
      if math.random() < 0.06 then spawn(s.x + math.random(-1, 1), s.y, 0.05, -0.22 - math.random() * 0.1, 160, 3) end
    end
  end
end

local function shadow_print(s, x, y, c)
  print(s, x + 1, y + 1, 0x000000)
  print(s, x, y, c)
end

local GDIR = { "S", "SE", "E", "NE", "N", "NW", "W", "SW" }

local function draw_gallery()
  cls(0x101018)
  camera()
  circfill(128, 186, 30, 0x1C1C28)
  rectfill(98, 182, 61, 9, 0x1C1C28)
  local g = GALLERY[gal.i]
  local name
  rectfill(0, 16, W, 32, 0x000000)
  if g.def then
    local o, z = gal.o, g.def.zoom
    local fr, flip = FOE.frame(o)
    local x = flip and 128 - (fr[3] - fr[5]) * z or 128 - fr[5] * z
    sspr(fr[1], fr[2], fr[3], fr[4], x, 186 - fr[6] * z, flip, false, z)
    local title = g.def.title
    print(title, (W - #title * 8) // 2 // 8 * 8, 16, g.def.boss and 0xE07050 or 0xD8C8A0)
    name = g.anim .. "  " .. GDIR[P.dir + 1] .. "  " .. o.f .. "/" .. #g.def.a[g.anim].t
    print(name, (W - #name * 8) // 2 // 8 * 8, 32, 0xE8C878)
  else
    local fr = HUNT[P.anim].d[P.dir + 1][P.f]
    sspr(fr[1], fr[2], fr[3], fr[4], 128 - fr[5] * 2, 186 - fr[6] * 2, false, false, 2)
    name = g.anim .. "  " .. GDIR[P.dir + 1] .. "  " .. P.f .. "/" .. #HUNT[P.anim].t
    print(name, (W - #name * 8) // 2 // 8 * 8, 16, 0xE8C878)
  end
  rectfill(0, 224, W, 32, 0x000000)
  print("left right: turn  Y: next", 24, 224, 0x8890A0)
  print("up down: animation  B: back", 16, 240, 0x8890A0)
end

-- the lamp's menu: rest, the paths (with what the next one costs), leave
local function draw_menu()
  rectfill(16, 40, 224, 208, 0x080608)
  rect(16, 40, 224, 208, 0x786040)
  print("HUNTER'S LAMP", 72, 48, 0xE8C878)
  local e = G.echoes .. " echoes"
  print(e, (W - #e * 8) // 2 // 8 * 8, 64, 0xC8A060)
  local n = #PATHS + 2
  local k = #G.slots + 1
  local cost = SLOT_COST[k]
  for i = 1, n do
    local y = 96 + (i - 1) * 16
    local name = i == 1 and "Rest" or i == n and "Leave" or PATHS[i - 1].name
    local sel = i == menu.i
    if sel then print(">", 24, y, 0xE8C878) end
    local col = sel and 0xF0E0C0 or 0x908878
    if i > 1 and i < n and (not cost or G.echoes < cost) then col = sel and 0x988870 or 0x585048 end
    local x = print(name, 40, y, col)
    if i > 1 and i < n then
      -- a rhombus for every time this path was taken (gold: the hunter's own,
      -- the first taken; ash: the others)
      local m = 0
      for _, p in ipairs(G.slots) do
        if p == i - 1 then
          local cx, c = x + 9 + m * 9, p == G.slots[1] and 0xC8A060 or 0x787068
          for r = 0, 6 do
            local hw = 3 - abs(r - 3)
            rectfill(cx - hw, y + 4 + r, hw * 2 + 1, 1, c)
          end
          m = m + 1
        end
      end
      if cost then
        local c = cost .. ""
        print(c, 232 - #c * 8, y, col)
      end
    end
  end
  local i = menu.i
  local lore = i == 1 and { "whole again; and the", "town wakes again" } or i == n and { "back to the hunt", "" } or
               (cost and PATHS[i - 1].lore or { "your paths are walked", "to their end" })
  print(lore[1], 24, 208, 0x686878)
  print(lore[2], 24, 224, 0x686878)
end

-- the pause, and the controls (keys as on the device used last)
local CONTROLS = {
  { "DPAD", "up", "walk" },
  { "A", "space", "blow, again: combo" },
  { "R1", "e", "heavy, hold: charge" },
  { "L1", "q", "lock on" },
  { "B", "x", "dodge, hold: run" },
  { "X", "c", "pistol: the parry" },
  { "Y", "v", "transform: the trick" },
  { "SELECT", "tab", "blood, to heal" },
  { "START", "enter", "this menu" },
}
local function draw_pause()
  rectfill(16, 32, 224, 208, 0x080608)
  rect(16, 32, 224, 208, 0x786040)
  if menu.page == "controls" then
    print("CONTROLS", 96, 48, 0xE8C878)
    local kb = lastinput() == "keyboard"
    for i, c in ipairs(CONTROLS) do
      local y = 64 + (i - 1) * 16
      prompt(kb and c[2] or c[1], 24, y)
      print(c[3], 80, y, 0xB0A890)
    end
    print("reeling, then A: visceral", 24, 208, 0x686878)
    return
  end
  print("PAUSE", 104, 48, 0xE8C878)
  for i, name in ipairs({ "Resume", "Controls", "Give up the hunt" }) do
    local y = 96 + (i - 1) * 32
    local sel = i == menu.i
    if sel then print(">", 40, y, 0xE8C878) end
    print(name, 56, y, sel and 0xF0E0C0 or 0x908878)
  end
end

-- the end of a hunt with no echoes left
local function draw_lost()
  cls(0x040202)
  print("THE HUNT IS", 40, 88, 0xA01818, 2)
  print("OVER", 96, 120, 0xA01818, 2)
  print("no echoes left to pay", 40, 168, 0x786850)
  if t > 90 then print("A: begin again", 72, 208, (t // 30) % 2 == 0 and 0xE8E0D0 or 0x988870) end
end

function _draw()
  if state == "gallery" then
    draw_gallery()
    return
  elseif state == "lost" then
    draw_lost()
    return
  end
  emit()
  local fire_near = draw_scene()
  if state == "title" then
    if t <= 150 then
      rectfill(0, 16, W, 48, 0x000000)
      print("YHARNAM", 96, 16, 0xE8C878)
      print("a town of endless night", 40, 32, 0x8890A0)
      print("X: animations", 72, 48, 0x686878)
    end
    rectfill(0, 208, W, 16, 0x000000)
    print("A: START", 96, 208, (t // 30) % 2 == 0 and 0xE8E0D0 or 0x988870)
  elseif state == "gallery" then
    -- drawn by draw_gallery
  else
    update_sound(fire_near)
    if banner_t > 0 and banner then
      local w = #banner * 8
      local x = (W - w) // 2 // 8 * 8
      rectfill(x - 8, 16, w + 16, 16, 0x000000)
      print(banner, x, 16, banner_t > 30 and 0xD8C8A0 or 0x786850)
    end
    local sh = P.shrine
    if sh and state == "play" then
      rectfill(40, 224, 176, 16, 0x000000)
      print(G.lit[sh.key] and "A: rest at the lamp" or "A: light the lamp", 48, 224, 0xE8C878)
    elseif near_lamp then
      rectfill(48, 224, 160, 16, 0x000000)
      print("A: light the lamp", 56, 224, 0xE8C878)
    end
    -- the echoes
    local e = G.echoes .. ""
    shadow_print(e, W - 8 - #e * 8, 240, 0xC8A060)
    circfill(W - 14 - #e * 8, 247, 2, 0xA01818)      -- a drop of blood
    -- what the slain left, rising
    for _, pp in ipairs(G.popups) do
      shadow_print(pp.s, floor(pp.x - cam_x) - #pp.s * 4, floor(pp.y - cam_y), pp.t > 20 and 0xE8C878 or 0x786040)
    end
    FOE.hud()
    -- health: a red bar, as the hunters have
    rectfill(7, 7, P.hpmax * 7 + 2, 6, 0x100808)
    if P.hp > 0 then rectfill(8, 8, P.hp * 7, 4, P.inv > 40 and 0xE04030 or 0xA01818) end
    if P.rally > 0 and P.hp > 0 then rectfill(8 + P.hp * 7, 8, min(P.rally, P.hpmax - P.hp) * 7, 4, 0xC87028) end
    -- stamina, green, under it
    rectfill(7, 14, P.stmax * 0.7 + 2, 4, 0x081008)
    if P.st > 0 then rectfill(8, 15, floor(P.st * 0.7), 2, P.st_wait > 0 and 0x488838 or 0x68B050) end
    if state == "lamp" then draw_menu() elseif state == "pause" then draw_pause() end
    if P.act == "dead" and died_t > 0 then
      local k = min(died_t, 40)
      rectfill(0, 104, W, 48, 0x080404)
      print("YOU DIED", 64, 112, k > 20 and 0xA01818 or 0x501010, 2)
    end
  end
end
